INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-top-server-domains', 'default-dashboard', 'qgw', 'SELECT domain, SUM( sessions ) AS sessions, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes, SUM( in_bytes + out_bytes ) AS bytes, SUM( in_pkts ) AS in_packets, SUM( out_pkts ) AS out_packets, SUM( in_pkts + out_pkts ) AS packets FROM top_server_domains WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND metric = ''${metric}'' AND ( ${filter} ) GROUP BY domain ORDER BY ${metric} DESC LIMIT ${limit}', 'Endpoints-Top Server Domains. Aggregate traffic sessions, bytes, and packets based on the server domains. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-top-server-fqdns', 'default-dashboard', 'qgw', 'SELECT fqdn, SUM( sessions ) AS sessions, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes, SUM( in_bytes + out_bytes ) AS bytes, SUM( in_pkts ) AS in_packets, SUM( out_pkts ) AS out_packets, SUM( in_pkts + out_pkts ) AS packets FROM top_server_fqdns WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND metric = ''${metric}'' AND ( ${filter} ) GROUP BY fqdn ORDER BY ${metric} DESC LIMIT ${limit}', 'Endpoints-Top Server FQDNs. Aggregate traffic sessions, bytes, and packets based on the server FQDNs. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-top-subscribers', 'default-dashboard', 'qgw', 'SELECT subscriber_id, SUM( sessions ) AS sessions, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes, SUM( in_bytes + out_bytes ) AS bytes, SUM( in_pkts ) AS in_packets, SUM( out_pkts ) AS out_packets, SUM( in_pkts + out_pkts ) AS packets FROM top_subscribers WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND metric = ''${metric}'' AND ( ${filter} ) GROUP BY subscriber_id ORDER BY ${metric} DESC LIMIT ${limit}', 'Endpoints-Top Subscribers. Aggregate traffic sessions, bytes, and packets based on the subscribers. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('default-top-applications', 'default-dashboard', 'qgw', 'SELECT app_name, SUM( sessions ) AS sessions, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes, SUM( in_bytes + out_bytes ) AS bytes, SUM( in_pkts ) AS in_packets, SUM( out_pkts ) AS out_packets, SUM( in_pkts + out_pkts ) AS packets FROM application_protocol_stat WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN ( ${vsys_id} ) AND app_name IS NOT NULL AND ( ${filter} ) GROUP BY app_name ORDER BY ${metric} DESC LIMIT ${limit}', 'Endpoints-Top Applications. Aggregate traffic sessions, bytes, and packets based on the applications. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-client-ips', 'user-defined dashboard', 'qgw', 'SELECT client_ip AS client_ip, SUM( sessions ) AS sessions, SUM( out_bytes ) AS out_bytes, SUM( in_bytes ) AS in_bytes, SUM( out_bytes + in_bytes ) AS bytes, SUM( out_pkts ) AS out_packets, SUM( in_pkts ) AS in_packets, SUM( out_pkts + in_pkts ) AS packets FROM top_client_ips WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND metric = ''${metric}'' AND ( ${filter} ) GROUP BY client_ip ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the client''s IP address. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-server-ips', 'user-defined dashboard', 'qgw', 'SELECT server_ip AS server_ip, SUM( sessions ) AS sessions, SUM( out_bytes ) AS out_bytes, SUM( in_bytes ) AS in_bytes, SUM( out_bytes + in_bytes ) AS bytes, SUM( out_pkts ) AS out_packets, SUM( in_pkts ) AS in_packets, SUM( out_pkts + in_pkts) AS packets FROM top_server_ips WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) AND metric = ''${metric}'' GROUP BY server_ip ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the server IP address. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-internal-ips', 'user-defined dashboard', 'qgw', 'SELECT internal_ip AS internal_ip, SUM( sessions ) AS sessions, SUM( out_bytes ) AS out_bytes, SUM( in_bytes ) AS in_bytes, SUM( out_bytes + in_bytes ) AS bytes, SUM( out_pkts ) AS out_packets, SUM( in_pkts ) AS in_packets, SUM( out_pkts + in_pkts ) AS packets FROM top_internal_ips WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) AND metric = ''${metric}'' GROUP BY internal_ip ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the internal IP address. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-external-ips', 'user-defined dashboard', 'qgw', 'SELECT external_ip AS external_ip, SUM( sessions ) AS sessions, SUM( out_bytes ) AS out_bytes, SUM( in_bytes ) AS in_bytes, SUM( out_bytes + in_bytes ) AS bytes, SUM( out_pkts ) AS out_packets, SUM( in_pkts ) AS in_packets, SUM( out_pkts + in_pkts ) AS packets FROM top_external_ips WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) AND metric = ''${metric}'' GROUP BY external_ip ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the external IP address. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-subscribers', 'user-defined dashboard', 'qgw', 'SELECT subscriber_id, SUM( sessions ) AS sessions, SUM( out_bytes ) AS out_bytes, SUM( in_bytes ) AS in_bytes, SUM( out_bytes + in_bytes ) AS bytes, SUM( out_pkts ) AS out_packets, SUM( in_pkts ) AS in_packets, SUM( out_pkts+ in_pkts ) AS packets FROM top_subscribers WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) AND metric = ''${metric}'' GROUP BY subscriber_id ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the subscribers. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-server-domains', 'user-defined dashboard', 'qgw', 'SELECT domain, SUM( sessions ) AS sessions, SUM( out_bytes ) AS out_bytes, SUM( in_bytes ) AS in_bytes, SUM( out_bytes + in_bytes ) AS bytes, SUM( out_pkts) AS out_packets, SUM( in_pkts ) AS in_packets, SUM( out_pkts + in_pkts ) AS packets FROM top_server_domains WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) AND metric = ''${metric}'' GROUP BY domain ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the server domains. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-server-fqdns', 'user-defined dashboard', 'qgw', 'SELECT fqdn, SUM( sessions ) AS sessions, SUM( out_bytes ) AS out_bytes, SUM( in_bytes ) AS in_bytes, SUM( out_bytes + in_bytes ) AS bytes, SUM( out_pkts ) AS out_packets, SUM( in_pkts ) AS in_packets, SUM( out_pkts + in_pkts ) AS packets FROM top_server_fqdns WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) AND metric = ''${metric}'' GROUP BY fqdn ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the server FQDNs. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-applications', 'user-defined dashboard', 'qgw', 'SELECT app_name, SUM( sessions ) AS sessions, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes, SUM( in_bytes + out_bytes ) AS bytes, SUM( in_pkts ) AS in_packets, SUM( out_pkts ) AS out_packets, SUM( in_pkts + out_pkts ) AS packets FROM application_protocol_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND app_name IS NOT NULL AND ( ${filter} ) GROUP BY app_name ORDER BY ${metric} DESC LIMIT ${limit}', 'Aggregate traffic sessions, bytes, and packets based on the applications. The ${metric} variable includes three options: sessions, bytes, and packets.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-network-throughput', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_in_bytes )* 8 / 5 AS avg_in_bits_per_sec, AVG( sum_out_bytes )* 8 / 5 AS avg_out_bits_per_sec, AVG( sum_bytes )* 8 / 5 AS avg_bits_per_sec, AVG( sum_in_bytes )/ 5 AS avg_in_bytes_per_sec, AVG( sum_out_bytes )/ 5 AS avg_out_bytes_per_sec, AVG( sum_bytes )/ 5 AS avg_bytes_per_sec, AVG( sum_in_pkts )/ 5 AS avg_in_pkts_per_sec, AVG( sum_out_pkts )/ 5 AS avg_out_pkts_per_sec, AVG( sum_pkts )/ 5 AS avg_pkts_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM( in_bytes ) AS sum_in_bytes, SUM( out_bytes ) AS sum_out_bytes, SUM( in_bytes + out_bytes ) AS sum_bytes, SUM( in_pkts ) AS sum_in_pkts, SUM( out_pkts ) AS sum_out_pkts, SUM( in_pkts + out_pkts ) AS sum_pkts FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', 'The calculation of average network throughput is capable of supporting two types of metrics, namely \"bytes\" and \"packets\".', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-new-sessions-per-second', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, avg( sum_sessions )/ 5 AS avg_sessions_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, sum( sessions ) AS sum_sessions FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-active-sessions', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_active_sessions ) AS avg_active_sessions FROM ( SELECT stat_time, SUM( max_active_sessions ) sum_active_sessions FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, device_id, vsys_id, MAX( active_sessions ) AS max_active_sessions FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S''), device_id, vsys_id ) GROUP BY stat_time ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-asymmetric-flows', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_bytes )* 8 / 5 AS avg_bits_per_sec, round( CASE WHEN sum( sum_closed_sessions ) = 0 THEN 0 ELSE SUM( sum_asymmetric_flows ) * 1.0 / SUM( sum_closed_sessions ) END, 4 ) * 100 AS percent_asymmetric_flows FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM( in_bytes ) AS sum_in_bytes, SUM( out_bytes ) AS sum_out_bytes, SUM( in_bytes + out_bytes ) AS sum_bytes, SUM( closed_sessions ) AS sum_closed_sessions, SUM( asymmetric_c2s_flows + asymmetric_s2c_flows ) AS sum_asymmetric_flows FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-traffic-shapping-policy-dropped-packets', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''${alignment_period}'', ''zero'')) AS stat_time, rule_id, SUM( in_drop_pkts + out_drop_pkts ) AS sum_dropped_packets FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''${alignment_period}'', ''zero'')), rule_id ORDER BY stat_time ASC LIMIT ${limit}', 'The dropped packets for different traffic shaping rules over a selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-traffic-shaping-policy-throughput', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, rule_id, AVG( sum_bytes )* 8 / 1 AS avg_bits_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, rule_id, SUM( in_bytes + out_bytes ) AS sum_bytes FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), rule_id ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), rule_id ORDER BY stat_time ASC LIMIT ${limit}', 'The throughput of traffic shaping rule over a selected time frame', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-service-chaining-policy-throughput', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, rule_id, AVG( sum_bytes )* 8 / 1 AS avg_bits_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, rule_id, SUM( sent_bytes + recv_bytes ) AS sum_bytes FROM service_chaining_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), rule_id ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), rule_id ORDER BY stat_time ASC LIMIT ${limit}', 'The throughput of the service chaining rule over a selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-application-usage', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, app_name, AVG( sum_in_bytes )* 8 / 15 AS avg_in_bits_per_sec, AVG( sum_out_bytes )* 8 / 15 AS avg_out_bits_per_sec, AVG( sum_bytes )* 8 / 15 AS avg_bits_per_sec, AVG( sum_in_pkts )/ 15 AS avg_in_pkts_per_sec, AVG( sum_out_pkts )/ 15 AS avg_out_pkts_per_sec, AVG( sum_pkts )/ 15 AS avg_pkts_per_sec, AVG( sum_sessions )/ 15 AS avg_sessions_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT15S'') AS stat_time, app_name, SUM( sessions ) AS sum_sessions, SUM( in_bytes ) AS sum_in_bytes, SUM( out_bytes ) AS sum_out_bytes, SUM( in_bytes + out_bytes ) AS sum_bytes, SUM( in_pkts ) AS sum_in_pkts, SUM( out_pkts ) AS sum_out_pkts, SUM( in_pkts + out_pkts ) AS sum_pkts FROM application_protocol_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) AND app_name IS NOT NULL GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT15S''), app_name ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), app_name ORDER BY stat_time ASC LIMIT ${limit}', 'Real-time traffic sessions, bytes, and packets of favorite applications over a selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-security-policy-hits-metric', 'user-defined dashboard', 'qgw', 'SELECT rule_id AS rule_id, SUM( hit_count ) AS hit_count, SUM( in_bytes + out_bytes ) AS bytes FROM security_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id ORDER BY ${metric} DESC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-proxy-policy-hits-by-manipulation-action', 'user-defined dashboard', 'qgw', 'SELECT rule_id AS rule_id, action AS action, sub_action AS sub_action, SUM( hit_count ) AS hit_count, SUM( in_bytes + out_bytes ) AS bytes FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id, action, sub_action ORDER BY ${metric} DESC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-security-policy-usage', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, rule_id, avg( sum_hit_count )/ 1 AS avg_hit_count_per_sec, avg( sum_bytes )* 8 / 1 AS avg_bits_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, rule_id, sum( hit_count ) AS sum_hit_count, sum( in_bytes + out_bytes ) AS sum_bytes FROM security_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), rule_id ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), rule_id ORDER BY stat_time ASC LIMIT ${limit}', 'The hit count and bytes of the favorite security policy rule over the selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-proxy-policy-usage', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, rule_id, avg( sum_hit_count )/ 1 AS avg_hit_count_per_sec, avg( sum_bytes )* 8 / 1 AS avg_bits_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, rule_id, sum( hit_count ) AS sum_hit_count, sum( in_bytes + out_bytes ) AS sum_bytes FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), rule_id ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), rule_id ORDER BY stat_time ASC LIMIT ${limit}', 'The hit count and bytes of the favorite proxy policy rule over the selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-proxy-ssl-intercept-pinning-trend', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( CASE WHEN pinning_status = 0 THEN sum_hit_count ELSE 0 END )/ 1 AS avg_not_pinning_hit_count_per_sec, AVG( CASE WHEN pinning_status = 1 THEN sum_hit_count ELSE 0 END )/ 1 AS avg_pinning_hit_count_per_sec, AVG( CASE WHEN pinning_status = 2 THEN sum_hit_count ELSE 0 END )/ 1 AS avg_maybe_pinning_hit_count_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, pinning_status, SUM( hit_count ) AS sum_hit_count, SUM( in_bytes + out_bytes ) AS sum_bytes FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND action = 2 AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), pinning_status ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', 'Monitor SSL Pinning over the selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-security-policy-hits-by-action', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, (CASE WHEN action = 1 THEN ''Monitor'' WHEN action = 2 THEN ''Intercept'' WHEN action = 16 THEN ''Deny'' WHEN action = 48 THEN ''Manipulation'' WHEN action = 96 THEN ''Allow'' WHEN action = 128 THEN ''Shunt'' ELSE concat( action ) END ) AS action, AVG( sum_hit_count )/ 1 AS avg_hit_count_per_sec, AVG( sum_bytes )* 8 / 1 AS avg_bits_per_sec, AVG( sum_packets )/ 1 AS avg_pkts_per_sec, SUM( sum_hit_count ) AS total_hit_count, SUM( sum_bytes ) AS total_bytes, SUM( sum_packets ) AS total_packets FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, action, SUM( hit_count ) AS sum_hit_count, SUM( in_bytes + out_bytes ) AS sum_bytes, SUM( in_pkts + out_pkts ) AS sum_packets FROM security_rule_hits WHERE __time >= ''${start}'' AND __time <  ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), action ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), action ORDER BY stat_time ASC LIMIT ${limit}', 'The security policy rule hit count, bytes, and packets of action over the selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-proxy-policy-hits-by-action', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, (CASE WHEN action = 2 THEN ''Intercept'' WHEN action = 3 THEN ''No Intercept'' WHEN action = 48 THEN ''Manipulation'' ELSE concat( action ) END ) AS action, AVG( sum_hit_count )/ 1 AS avg_hit_count_per_sec, SUM( sum_hit_count ) AS total_hit_count FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, action AS action, SUM( hit_count ) AS sum_hit_count FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), action ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), action ORDER BY stat_time ASC LIMIT ${limit}', 'The proxy Intercept policy hit the count of action over the selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-proxy-manipulation-policy-hits-by-action', 'user-defined dashboard', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, action AS action, AVG( sum_hit_count )/ 1 AS avg_hit_count_per_sec, SUM( sum_hit_count ) AS total_hit_count FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, sub_action AS action, SUM( hit_count ) AS sum_hit_count FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND action = 48 AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S''), sub_action ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')), action ORDER BY stat_time ASC LIMIT ${limit}', 'The proxy manipulation policy hit the count of action over the selected time frame.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-security-policy-hits', 'user-defined dashboard', 'qgw', 'SELECT rule_id, action, SUM( hit_count) AS hit_count, SUM( in_bytes + out_bytes ) AS bytes FROM security_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id, action ORDER BY hit_count DESC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-top-proxy-policy-hits', 'user-defined dashboard', 'qgw', 'SELECT rule_id, SUM( hit_count ) AS hit_count, SUM( in_bytes + out_bytes ) AS bytes FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id ORDER BY hit_count DESC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('security-rule-hits-summary', 'security rule hits', 'qgw', 'SELECT rule_id, SUM(hit_count) as hits, SUM(in_bytes + out_bytes) as bytes FROM security_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND rule_id IN ( ${rule_id} ) AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The hit count of specific rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('security-rule-hits-trend', 'security rule hits', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) AS stat_time, SUM(hit_count) AS hits FROM security_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND rule_id IN (${rule_id}) AND vsys_id IN (${vsys_id}) AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) LIMIT ${limit}', 'The trend of hit count by specific rule over a period of time.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('security-rule-hits-first-and-last-hit', 'security rule hits', 'qgw', 'SELECT rule_id, DATE_FORMAT(MIN(__time) ,''%Y-%m-%d %H:%i:%s'') AS first_hit, DATE_FORMAT(MAX(__time) ,''%Y-%m-%d %H:%i:%s'') AS last_hit FROM security_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND rule_id IN( ${rule_id}) AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The time of the first and last hit for policy rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('security-rule-hits-current-throughput', 'security rule hits', 'qgw', 'SELECT SUM(in_bytes)* 8 / 15 AS in_bps, SUM(out_bytes)* 8 / 15 AS out_bps, SUM(in_bytes + out_bytes)* 8 / 15 AS total_bps FROM security_rule_hits WHERE __time >= FROM_UNIXTIME(UNIX_TIMESTAMP(now())-30) AND __time < FROM_UNIXTIME(UNIX_TIMESTAMP(now())-15) AND vsys_id IN ( ${vsys_id} ) AND rule_id IN ( ${rule_id} ) AND ( ${filter} )', 'To calculate the current security hit throughput, the metrics for each appliance are averaged over a 15-second interval. Additionally, the data ingestion latency is also set at 15 seconds.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('statistics-rule-hits-first-and-last-hit', 'statistics rule hits', 'qgw', 'SELECT rule_id, DATE_FORMAT( min( __time), ''%Y-%m-%d %H:%i:%s'' ) AS first_hit, DATE_FORMAT( max( __time ), ''%Y-%m-%d %H:%i:%s'' ) AS last_hit FROM statistics_rule_hits WHERE __time >= ''${start}'' AND __time <''${end}'' AND rule_id IN( ${rule_id} ) AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The time of the first and last hit for statistics policy rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('statistics-rule-hits-summary', 'statistics rule hits', 'qgw', 'SELECT rule_id, sum( hit_count ) AS hits, sum( in_bytes + out_bytes ) AS bytes FROM statistics_rule_hits WHERE __time >= ''${start}'' AND __time <''${end}'' AND rule_id IN ( ${rule_id} ) AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The hit count of specific rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('statistics-rule-hits-trend', 'statistics rule hits', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_in_bytes )* 8 / 1 AS avg_in_bits_per_sec, AVG( sum_out_bytes )* 8 / 1 AS avg_out_bits_per_sec, AVG( sum_bytes )* 8 / 1 AS avg_bits_per_sec, SUM( sum_in_bytes ) AS total_in_bytes, SUM( sum_out_bytes ) AS total_out_bytes, SUM( sum_bytes ) AS total_bytes, AVG( sum_hit_count )/ 1 AS avg_hit_count_per_sec, SUM( sum_hit_count ) AS total_hit_count FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') AS stat_time, sum( in_bytes ) AS sum_in_bytes, sum( out_bytes ) AS sum_out_bytes, sum( in_bytes + out_bytes ) AS sum_bytes, sum( hit_count ) AS sum_hit_count FROM statistics_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND rule_id IN (${rule_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT1S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('proxy-rule-hits-summary', 'proxy rule hits', 'qgw', 'SELECT rule_id, SUM( hit_count ) AS hits, SUM( in_bytes + out_bytes ) AS bytes FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND rule_id IN ( ${rule_id} ) AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The hit count of specific rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('proxy-rule-hits-trend', 'proxy rule hits', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) AS stat_time, SUM( hit_count ) AS hits FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND rule_id IN ( ${rule_id} ) AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('proxy-rule-hits-first-and-last-hit', 'proxy rule hits', 'qgw', 'SELECT rule_id, DATE_FORMAT( MIN( __time), ''%Y-%m-%d %H:%i:%s'' ) AS first_hit, DATE_FORMAT( MAX( __time ), ''%Y-%m-%d %H:%i:%s'' ) AS last_hit FROM proxy_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND rule_id IN( ${rule_id} ) AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The time of the first and last hit for policy rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('proxy-rule-hits-current-throughput', 'proxy rule hits', 'qgw', ' SELECT SUM( in_bytes )* 8 / 15 AS in_bps, SUM( out_bytes )* 8 / 15 AS out_bps, SUM( in_bytes + out_bytes )* 8 / 15 AS total_bps FROM proxy_rule_hits WHERE __time >= FROM_UNIXTIME( UNIX_TIMESTAMP( now())- 30 ) AND __time < FROM_UNIXTIME( UNIX_TIMESTAMP( now())- 15 ) AND vsys_id IN ( ${vsys_id} ) AND rule_id IN ( ${rule_id} ) AND ( ${filter} )', 'To calculate the current policy hit throughput, the metrics for each appliance are averaged over a 15-second interval. Additionally, the data ingestion latency is also set at 15 seconds.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('shaping-rule-hits-profiles', 'shaping rule hits', 'qgw', 'SELECT profile_id, SUM( in_bytes + out_bytes ) AS bytes, SUM( in_pkts + out_pkts ) AS packets, SUM( in_drop_pkts + out_drop_pkts ) AS drops, MAX( in_max_latency_us + out_max_latency_us ) AS max_latency_us, AVG( in_queue_len + out_queue_len ) AS avg_q, MAX( in_queue_len + out_queue_len ) AS max_q FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND profile_id IN ( ${profile_id} ) AND ( ${filter} ) GROUP BY profile_id', 'The hit count of specific shaping profiles.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('shaping-rule-hits-first-and-last-hit', 'shaping rule hits', 'qgw', 'SELECT rule_id, DATE_FORMAT( MAX( __time), ''%Y-%m-%d %H:%i:%s'' ) AS last_hit, DATE_FORMAT( MIN( __time ), ''%Y-%m-%d %H:%i:%s'' ) AS first_hit FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN( ${vsys_id} ) AND rule_id IN ( ${rule_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The time of the first and last hit for policy rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('shaping-rule-hits-transferred-bytes', 'shaping rule hits', 'qgw', 'SELECT rule_id, SUM( in_bytes + out_bytes ) AS total_bytes FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND rule_id IN ( ${rule_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The number of transferred bytes of specific shaping rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('shaping-rule-hits-profile-first-and-last-hit', 'shaping rule hits', 'qgw', 'SELECT profile_id, DATE_FORMAT( max( __time), ''%Y-%m-%d %H:%i:%s'' ) AS last_hit, DATE_FORMAT( min( __time ), ''%Y-%m-%d %H:%i:%s'' ) AS first_hit, SUM( in_drop_pkts + out_drop_pkts ) AS drops FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN( ${vsys_id} ) AND profile_id IN ( ${profile_id} ) AND ( ${filter} ) GROUP BY profile_id', 'The time of the first and last hit for shaping profiles.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('shaping-rule-hits-profile-hit-current-throughput', 'shaping rule hits', 'qgw', 'SELECT SUM( in_bytes )* 8 / 15 AS in_bps, SUM( out_bytes )* 8 / 15 AS out_bps, SUM( in_pkts )* 8 / 15 AS in_pps, SUM( out_pkts )* 8 / 15 AS out_pps, MAX( in_max_latency_us + out_max_latency_us ) AS max_latency_us, AVG( in_queue_len + out_queue_len ) AS avg_q, MAX( in_queue_len + out_queue_len ) AS max_q FROM traffic_shaping_rule_hits WHERE __time >= FROM_UNIXTIME( UNIX_TIMESTAMP( now())- 30 ) AND __time < FROM_UNIXTIME( UNIX_TIMESTAMP( now())- 15 ) AND vsys_id IN ( ${vsys_id} ) AND profile_id IN ( ${profile_id} ) AND ( ${filter} )', 'To calculate the current shaping profile hit throughput, the metrics for each appliance are averaged over a 15-second interval. Additionally, the data ingestion latency is also set at 15 seconds.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('shaping-rule-hits-throughput-trend', 'shaping rule hits', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) AS stat_time, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND rule_id IN ( ${rule_id} ) AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('shaping-rule-hits-profile-throughput-trend', 'shaping rule hits', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) AS stat_time, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND profile_id IN ( ${profile_id} ) AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('service-chaining-rule-hits-throughput-trend', 'service chaining rule hits', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) AS stat_time, SUM( sent_bytes ) AS sent_bytes, SUM( recv_bytes ) AS received_bytes FROM service_chaining_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND rule_id IN ( ${rule_id} ) AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('service-chaining-rule-hits-function-forwarder-profile-throughput-trend', 'service chaining rule hits', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) AS stat_time, SUM( sent_bytes ) AS sent_bytes, SUM( recv_bytes ) AS received_bytes FROM service_chaining_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND sff_profile_id IN ( ${sff_profile_id} ) AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('service-chaining-rule-hits-function-profile-throughput-trend', 'service chaining rule hits', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) AS stat_time, SUM( sent_bytes ) AS sent_bytes, SUM( recv_bytes ) AS received_bytes FROM service_chaining_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND sf_profile_id IN ( ${sf_profile_id}) AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('service-chaining-rule-hits-summary', 'service chaining rule hits', 'qgw', 'SELECT rule_id, SUM(sent_bytes) as sent_bytes, SUM(recv_bytes) as received_bytes, SUM(sent_pkts) as sent_packets, SUM(recv_pkts) as received_packets FROM service_chaining_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND rule_id IN ( ${rule_id} ) AND ( ${filter} ) GROUP BY rule_id', 'The hit count of specific rules.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('service-chaining-rule-hits-function-forwarder-profile-summary', 'service chaining rule hits', 'qgw', 'SELECT sff_profile_id, SUM( sent_bytes ) AS sent_bytes, SUM( recv_bytes ) AS received_bytes, SUM( sent_pkts ) AS sent_packets, SUM( recv_pkts ) AS received_packets FROM service_chaining_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND sff_profile_id IN ( ${sff_profile_id} ) AND ( ${filter} ) GROUP BY sff_profile_id', 'The hit count of specific function forwarder profiles.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('service-chaining-rule-hits-function-profile-summary', 'service chaining rule hits', 'qgw', 'SELECT sf_profile_id, SUM( sent_bytes ) AS sent_bytes, SUM( recv_bytes ) AS received_bytes, SUM( sent_pkts ) AS sent_packets, SUM( recv_pkts ) AS received_packets FROM service_chaining_rule_hits WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND sf_profile_id IN ( ${sf_profile_id} ) AND ( ${filter} ) GROUP BY sf_profile_id', 'The hit count of specific function profiles.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('service-function-status-first-and-last-active-time', 'service chaining rule hits', 'qgw', 'SELECT sf_profile_id, sf_status, CASE WHEN last_active_time = 0 THEN '''' ELSE FROM_UNIXTIME(last_active_time) END AS last_active_time, CASE WHEN last_inactive_time = 0 THEN '''' ELSE FROM_UNIXTIME(last_inactive_time) END AS last_inactive_time FROM ( SELECT sf_profile_id, LATEST(sf_status) as sf_status, MAX(CASE WHEN sf_status = 1 THEN UNIX_TIMESTAMP(__time) ELSE 0 END) as last_active_time, MAX(CASE WHEN sf_status = 0 THEN UNIX_TIMESTAMP(__time) ELSE 0 END) as last_inactive_time FROM service_function_status WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND sf_profile_id IN ( ${sf_profile_id} ) AND ( ${filter} ) GROUP BY sf_profile_id)', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('radius-stat-summary', 'radius records', 'qgw', 'SELECT COUNT(DISTINCT ( framed_ip )) AS active_ip_num, SUM( acct_session_time ) AS online_duration FROM ( SELECT any( framed_ip ) AS framed_ip, MAX( acct_session_time ) AS acct_session_time FROM radius_onff_log WHERE account = ''${subscriber_id}'' AND event_timestamp >= ''${start}'' AND event_timestamp < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY acct_session_id)', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('radius-subscriber-framed-ip', 'radius records', 'qgw', 'SELECT DISTINCT( framed_ip ) AS framed_ip FROM radius_onff_log WHERE account = ''${subscriber_id}'' AND event_timestamp >= ''${start}'' AND event_timestamp < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} )', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('radius-subscriber-detail', 'radius records', 'qgw', 'SELECT MAX(IF( acct_status_type = 1, event_timestamp, 0 )) AS start_time, MAX(IF( acct_status_type = 2, event_timestamp, 0 )) AS end_time, any( framed_ip ) AS ip, MAX( acct_session_time ) AS online_duration FROM radius_onff_log WHERE account = ''${subscriber_id}'' AND event_timestamp >= ''${start}'' AND event_timestamp < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY acct_session_id ORDER BY start_time DESC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('object-statistics-list', 'object statistics', 'qgw', 'SELECT object_id, SUM( in_bytes) AS in_bytes, SUM( out_bytes ) AS out_bytes, SUM( bytes ) AS bytes, SUM( new_in_sessions ) AS new_in_sessions, SUM( new_out_sessions ) AS new_out_sessions, SUM( sessions ) AS sessions FROM object_statistics WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN( ${vsys_id} ) AND object_id IN ( ${object_id} ) AND ( ${filter} ) GROUP BY object_id ORDER BY ${metric} ${order} LIMIT ${limit}', 'A list of objects sorted by ${metric}. The ${metric} variable includes [ incoming_bytes| outgoing_bytes| bytes| new_incoming_sessions| new_outgoing_sessions| sessions].', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('object-statistics-summary', 'object statistics', 'qgw', 'SELECT SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes, SUM( bytes ) AS bytes, SUM( new_in_sessions ) AS new_in_sessions, SUM( new_out_sessions ) AS new_out_sessions, SUM( sessions ) AS sessions FROM object_statistics WHERE __time >= ''${start}'' AND __time <  ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND object_id in (${object_id}) AND item_id in (${item_id}) AND ( ${filter} )', 'Aggregate traffic sessions and bytes based on the objects.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('object-statistics-item-list', 'object statistics', 'qgw', 'SELECT item_id, SUM( in_bytes) AS in_bytes, SUM( out_bytes ) AS out_bytes, SUM( bytes ) AS bytes, SUM( new_in_sessions ) AS new_in_sessions, SUM( new_out_sessions ) AS new_out_sessions, SUM( sessions ) AS sessions FROM object_statistics WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN( ${vsys_id} ) AND object_id IN (${object_id}) AND item_id IN (${item_id}) AND item_id > 0 AND ( ${filter} ) GROUP BY item_id ORDER BY ${metric} ${order} LIMIT ${limit}', 'A list of items sorted by ${metric} with specific Object ID(${filters}). The ${metric} variable includes [ incoming_bytes| outgoing_bytes| bytes| new_incoming_sessions| new_outgoing_sessions| sessions].', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('object-statistics-trend', 'object statistics', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, SUM( in_bytes ) AS in_bytes, AVG( in_bytes )* 8 / 15 AS avg_in_bits_per_sec, SUM( out_bytes ) AS out_bytes, AVG( out_bytes )* 8 / 15 AS avg_out_bits_per_sec, SUM( bytes ) AS bytes, AVG( bytes )* 8 / 15 AS avg_bits_per_sec, SUM( new_in_sessions ) AS new_in_sessions, AVG( new_in_sessions )/ 15 AS avg_new_in_sessions_per_sec, SUM( new_out_sessions ) AS new_out_sessions, AVG( new_out_sessions )/ 15 AS avg_new_out_sessions_per_sec, SUM( sessions ) AS sessions, AVG( sessions )/ 15 AS avg_sessions_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT15S'') AS stat_time, SUM( in_bytes ) AS in_bytes, SUM( out_bytes ) AS out_bytes, SUM( bytes ) AS bytes, SUM( new_in_sessions ) AS new_in_sessions, SUM( new_out_sessions ) AS new_out_sessions, SUM( sessions ) AS sessions FROM object_statistics WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND object_id in (${object_id}) AND item_id in (${item_id}) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT15S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', 'The traffic trend by an object or item.', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('statistics-rule-line-chart-template', 'statistics rule', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time [[,AVG(${metric_in_bytes})*8/15 AS avg_in_bits_per_sec]] [[,AVG(${metric_out_bytes})*8/15 AS avg_out_bits_per_sec]] [[,AVG(${metric_bytes})*8/15 AS avg_bits_per_sec]] [[,AVG(${metric_new_c2s_flows})/15 AS avg_new_c2s_flows_per_sec]] [[,AVG(${metric_new_s2c_flows})/15 AS avg_new_s2c_flows_per_sec]] [[,AVG(${metric_new_in_sessions})/15 AS avg_new_in_sessions_per_sec]] [[,AVG(${metric_new_out_sessions})/15 AS avg_new_out_sessions_per_sec]] [[,AVG(${metric_sessions})/15 AS avg_sessions_per_sec]] [[,AVG(${metric_new_unestablished_sessions})/15 AS avg_new_unestablished_sessions_per_sec]] [[,AVG(${metric_syn_pkts})/15 AS avg_syn_pkts_per_sec]] [[,APPROX_COUNT_DISTINCT_HLLD(${metric_session_identifier_sketch}) AS active_sessions]] [[,APPROX_COUNT_DISTINCT_HLLD(${metric_client_ip_sketch}) AS unique_client_ips]] [[,APPROX_COUNT_DISTINCT_HLLD(${metric_server_ip_sketch}) AS unique_server_ips]] [[,APPROX_QUANTILE_HDR(${metric_in_latency_ms_sketch},0.5) AS median_tcp_in_latency_ms]] [[,APPROX_QUANTILE_HDR(${metric_in_latency_ms_sketch},0.95) AS p95th_tcp_in_latency_ms]] [[,APPROX_QUANTILE_HDR(${metric_in_latency_ms_sketch},0.99) AS p99th_tcp_in_latency_ms]] [[,APPROX_QUANTILE_HDR(${metric_out_latency_ms_sketch},0.5) AS median_tcp_out_latency_ms]] [[,APPROX_QUANTILE_HDR(${metric_out_latency_ms_sketch},0.95) AS p95th_tcp_out_latency_ms]] [[,APPROX_QUANTILE_HDR(${metric_out_latency_ms_sketch},0.99) AS p99th_tcp_out_latency_ms]] [[,APPROX_QUANTILE_HDR(${metric_latency_ms_sketch},0.5) AS median_tcp_latency_ms]] [[,APPROX_QUANTILE_HDR(${metric_latency_ms_sketch},0.95) AS p95th_tcp_latency_ms]] [[,APPROX_QUANTILE_HDR(${metric_latency_ms_sketch},0.99) AS p99th_tcp_latency_ms]] FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT15S'') AS stat_time [[,SUM(${metric_in_bytes}) AS in_bytes]] [[,SUM(${metric_out_bytes}) AS out_bytes]] [[,SUM(${metric_bytes}) AS bytes]] [[,SUM(${metric_new_c2s_flows}) AS new_c2s_flows]] [[,SUM(${metric_new_s2c_flows}) AS new_s2c_flows]] [[,SUM(${metric_new_in_sessions}) AS new_in_sessions]] [[,SUM(${metric_new_out_sessions}) AS new_out_sessions]] [[,SUM(${metric_sessions}) AS sessions]] [[,SUM(${metric_new_unestablished_sessions}) AS new_unestablished_sessions]] [[,SUM(${metric_syn_pkts}) AS syn_pkts]] [[,HLLD(${metric_session_identifier_sketch}) AS session_identifier_sketch]] [[,HLLD(${metric_client_ip_sketch}) AS client_ip_sketch]] [[,HLLD(${metric_server_ip_sketch}) AS server_ip_sketch]] [[,HDR_HISTOGRAM(${metric_in_latency_ms_sketch}) AS in_latency_ms_sketch]] [[,HDR_HISTOGRAM(${metric_out_latency_ms_sketch}) AS out_latency_ms_sketch]] [[,HDR_HISTOGRAM(${metric_latency_ms_sketch}) AS latency_ms_sketch]] FROM statistics_rule WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND rule_id = ${rule_id} AND template_id = ${template_id} AND chart_id = ${chart_id} AND version = ${version} AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT15S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('statistics-rule-histogram-chart-template', 'statistics rule', 'qgw', 'SELECT [[HDR_GET_PERCENTILES(HDR_HISTOGRAM(${metric_in_latency_ms_sketch}), 2) AS tcp_in_latency, HDR_GET_QUANTILES(HDR_HISTOGRAM(${metric_in_latency_ms_sketch}), 0.5,0.95,0.99) as tcp_in_latency_quantiles]] [[,HDR_GET_PERCENTILES(HDR_HISTOGRAM(${metric_out_latency_ms_sketch}), 2) AS tcp_out_latency ,HDR_GET_QUANTILES(HDR_HISTOGRAM(${metric_out_latency_ms_sketch}), 0.5,0.95,0.99) as tcp_out_latency_quantiles]] [[,HDR_GET_PERCENTILES(HDR_HISTOGRAM(${metric_latency_ms_sketch}), 2) AS tcp_latency ,HDR_GET_QUANTILES(HDR_HISTOGRAM(${metric_latency_ms_sketch}), 0.5,0.95,0.99) as tcp_latency_quantiles]] FROM statistics_rule WHERE __time >= ''${start}''AND __time < ''${end}''AND vsys_id IN ( ${vsys_id} ) AND rule_id = ${rule_id} AND template_id = ${template_id} AND chart_id = ${chart_id} AND version = ${version} AND ( ${filter} ) LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('statistics-rule-table-or-bar-chart-template', 'statistics rule', 'qgw', 'SELECT [[${dimension_client_ip} AS client_ip]] [[,${dimension_server_ip} AS server_ip]] [[,${dimension_server_fqdn} AS server_fqdn]] [[,${dimension_server_domain} AS server_domain]] [[,${dimension_application} AS application]] [[,${dimension_fqdn_category} AS fqdn_category]] [[,${dimension_client_ip_object} AS client_ip_object]] [[,${dimension_server_ip_object} AS server_ip_object]] [[,sum(${metric_in_bytes}) AS in_bytes]] [[,sum(${metric_out_bytes}) AS out_bytes]] [[,sum(${metric_bytes}) AS bytes]] [[,sum(${metric_new_c2s_flows}) AS new_c2s_flows]] [[,sum(${metric_new_s2c_flows}) AS new_s2c_flows]] [[,sum(${metric_new_in_sessions}) AS new_in_sessions]] [[,sum(${metric_new_out_sessions}) AS new_out_sessions]] [[,sum(${metric_sessions}) AS sessions]] [[,sum(${metric_new_unestablished_sessions}) AS new_unestablished_sessions]] [[,sum(${metric_syn_pkts}) AS syn_pkts]] [[,APPROX_COUNT_DISTINCT_HLLD(${metric_session_identifier_sketch}) AS active_sessions]] [[,APPROX_COUNT_DISTINCT_HLLD(${metric_client_ip_sketch}) AS unique_client_ips]] [[,APPROX_COUNT_DISTINCT_HLLD(${metric_server_ip_sketch}) AS unique_server_ips]] FROM statistics_rule WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id in (${vsys_id}) AND rule_id = ${rule_id} AND template_id = ${template_id} AND chart_id = ${chart_id} AND version = ${version} AND ( ${filter} ) GROUP BY [[${dimension_client_ip}]] [[,${dimension_server_ip}]] [[,${dimension_server_fqdn}]] [[,${dimension_server_domain}]] [[,${dimension_application}]] [[,${dimension_fqdn_category}]] [[,${dimension_client_ip_object}]] [[,${dimension_server_ip_object}]] ORDER BY [[${metric_in_bytes} ${order}]] [[,${metric_out_bytes} ${order}]] [[,${metric_bytes} ${order}]] [[,${metric_new_c2s_flows} ${order}]] [[,${metric_new_s2c_flows} ${order}]] [[,${metric_new_in_sessions} ${order}]] [[,${metric_new_out_sessions} ${order}]] [[,${metric_sessions} ${order}]] [[,${metric_new_unestablished_sessions} ${order}]] [[,${metric_syn_pkts} ${order}]] [[,${metric_active_sessions} ${order}]] [[,${metric_unique_client_ips} ${order}]] [[,${metric_unique_server_ips} ${order}]] LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-dataset-traffic-statistics-metrics', 'Traffic summary for report predefined dataset', 'qgw', 'SELECT COUNT(DISTINCT(device_id)) AS device_num, SUM(sum_bytes) AS total_bytes_transferred, SUM(sum_pkts) AS total_packets_transferred, SUM(sum_sessions) AS total_new_sessions , SUM(sum_closed_sessions) AS total_closed_sessions, SUM(sum_sessions)/ ${timestampdiff_second} AS avg_new_sessions_per_second, SUM(sum_bytes)* 8 / ${timestampdiff_second} AS avg_bits_per_second, SUM(sum_pkts)/ ${timestampdiff_second} AS avg_packets_per_second, SUM(avg_active_sessions) AS avg_active_sessions, round(CASE WHEN SUM(sum_closed_sessions) = 0 THEN 0 ELSE SUM(sum_asymmetric_flows) * 1.0 / SUM(sum_closed_sessions) END, 4) * 100 AS percent_asymmetric_flows FROM ( SELECT device_id, vsys_id, SUM(in_bytes + out_bytes) AS sum_bytes, SUM(in_pkts + out_pkts) AS sum_pkts, SUM(sessions) AS sum_sessions, SUM(closed_sessions) AS sum_closed_sessions, AVG(active_sessions) AS avg_active_sessions, SUM(asymmetric_c2s_flows + asymmetric_s2c_flows) AS sum_asymmetric_flows FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY device_id, vsys_id )', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-dataset-traffic-summary-throughput', 'Traffic summary for report predefined dataset', 'qgw', '\nSELECT FROM_UNIXTIME( TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'') ) AS stat_time, AVG(sum_in_bytes) * 8 / 5 AS avg_in_bits_per_sec, AVG(sum_out_bytes) * 8 / 5 AS avg_out_bits_per_sec, AVG(sum_bytes) * 8 / 5 AS avg_bits_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM(in_bytes) AS sum_in_bytes, SUM(out_bytes) AS sum_out_bytes, SUM(in_bytes + out_bytes) AS sum_bytes FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id}) AND (${filter}) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME( TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'') ) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('predefined-dataset-traffic-summary-new-sessions-per-second', 'Traffic summary for report predefined dataset', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG(sum_sessions)/ 5 AS avg_sessions_per_sec FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM(sessions) AS sum_sessions FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'')) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('dos-threat-map-top-source-countries', 'dos threat map', 'qgw', 'SELECT arrayJoin(splitByString('','',source_country_list)) AS source_country, count(*) AS count FROM dos_event WHERE start_time >= UNIX_TIMESTAMP(''${start}'') AND start_time < UNIX_TIMESTAMP(''${end}'') AND notEmpty(source_country_list) AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY arrayJoin(splitByString('','',source_country_list)) ORDER BY count DESC LIMIT ${limit}', '', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('dos-threat-map-top-destination-countries', 'dos threat map', 'qgw', 'SELECT destination_country, COUNT(*) AS count FROM dos_event WHERE start_time >= UNIX_TIMESTAMP(''${start}'') AND start_time < UNIX_TIMESTAMP(''${end}'') AND vsys_id IN (${vsys_id}) AND ( ${filter} ) GROUP BY destination_country ORDER BY count DESC LIMIT ${limit}', '', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('dos-threat-map-top-victims', 'dos threat map', 'qgw', 'SELECT destination_ip, count(*) AS count FROM dos_event WHERE start_time >= UNIX_TIMESTAMP(''${start}'') AND start_time < UNIX_TIMESTAMP(''${end}'') AND vsys_id IN (${vsys_id}) AND ( ${filter} ) GROUP BY destination_ip ORDER BY count DESC LIMIT ${limit}', '', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('dos-threat-map-attack-type', 'dos threat map', 'qgw', 'SELECT attack_type, count(*) AS count FROM dos_event WHERE start_time >= UNIX_TIMESTAMP(''${start}'') AND start_time < UNIX_TIMESTAMP(''${end}'') AND vsys_id IN (${vsys_id}) AND ( ${filter} ) GROUP BY attack_type ORDER BY attack_type LIMIT ${limit}', '', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('dos-threat-map-severity', 'dos threat map', 'qgw', 'SELECT severity, count(*) AS count FROM dos_event WHERE start_time >= UNIX_TIMESTAMP(''${start}'') AND start_time < UNIX_TIMESTAMP(''${end}'') AND vsys_id IN (${vsys_id}) AND ( ${filter} ) GROUP BY severity ORDER BY severity LIMIT ${limit}', '', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('dos-threat-map-destination-ip-distribution', 'dos threat map', 'qgw', 'SELECT destination_ip, IP_TO_GEO(destination_ip) AS destination_geo, any(destination_country) AS destination_country, groupUniqArray(arrayJoin(splitByString('','', source_country_list))) AS source_coutries, MAX(bit_rate) AS max_bit_rate, MAX(packet_rate) AS max_packet_rate, MAX(session_rate) AS max_session_rate, MIN(start_time) AS first_active_time, MAX(end_time) AS last_active_time, MAX_DURATION(end_time, 600) AS max_duration, groupUniqArray(attack_type) AS attack_type, count(*) AS count FROM dos_event WHERE start_time >= UNIX_TIMESTAMP(''${start}'') AND start_time < UNIX_TIMESTAMP(''${end}'') AND vsys_id IN (${vsys_id}) AND ( ${filter} ) GROUP BY destination_ip ORDER BY count DESC LIMIT ${limit}', '', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('dos-threat-map-attack-connection', 'dos threat map', 'qgw', 'SELECT start_time, destination_ip, IP_TO_GEO(destination_ip) AS destination_geo, destination_country, source_country_list, attack_type, severity, bit_rate, packet_rate, session_rate FROM dos_event WHERE start_time >= UNIX_TIMESTAMP(''${start}'') AND start_time < UNIX_TIMESTAMP(''${end}'') AND vsys_id IN (${vsys_id}) AND ( ${filter} ) ORDER BY start_time ASC LIMIT ${limit}', '', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('dos-events-summary', 'dos events', 'qgw', 'SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(start_time, ''${alignment_period}'', ''zero'')) AS stat_time, attack_type AS type, count(*) AS count FROM dos_event WHERE start_time >= UNIX_TIMESTAMP(''${start}'') AND start_time < UNIX_TIMESTAMP(''${end}'') AND vsys_id IN (${vsys_id}) AND ( ${filter} ) GROUP BY stat_time, attack_type ORDER BY stat_time ASC LIMIT ${limit}', '', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('dos-events-attack-logs', 'dos events', 'qgw', 'SELECT log_id, attack_type, source_country_list, source_ip_list, destination_ip, destination_country, severity, start_time, end_time, conditions, bit_rate, packet_rate, session_rate FROM dos_event WHERE start_time >= UNIX_TIMESTAMP(''${start}'') AND start_time < UNIX_TIMESTAMP(''${end}'') AND vsys_id IN (${vsys_id}) AND ( ${filter} ) ORDER BY start_time DESC LIMIT ${limit}', '', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('dos-events-destination-ip-traffic-trend', 'dos events', 'qgw', ' SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) AS stat_time, AVG(session_rate) AS session_rate, AVG(packet_rate) AS packet_rate, AVG(bit_rate) AS bit_rate FROM traffic_top_destination_ip_metrics_log WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN (${vsys_id}) AND destination_ip = ''${destination_ip}'' AND attack_type = ''${attack_type}'' AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) LIMIT ${limit}', '', '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('All Fields Query (default)', 'trouble-shooting', 'clickhouse', 'SELECT * FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('All Fields Query order by Time desc', 'trouble-shooting', 'clickhouse', 'SELECT * FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ORDER BY common_recv_time DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('All Fields Query order by Time asc', 'trouble-shooting', 'clickhouse', 'SELECT * FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ORDER BY common_recv_time asc LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('All Fields Query by Filter', 'trouble-shooting', 'clickhouse', 'SELECT * FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_client_ip=''${client_ip}'' ORDER BY common_recv_time DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Default Fields Query by Filter', 'trouble-shooting', 'clickhouse', 'SELECT toDateTime(common_recv_time) AS common_recv_time , common_log_id , common_client_ip , common_client_port , common_server_ip , common_server_port FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_client_ip=''${client_ip}'' ORDER BY common_recv_time DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('All Fields Query (sub query by time)', 'trouble-shooting', 'clickhouse', 'SELECT * FROM tsg_galaxy_v3.session_record AS session_record WHERE toDateTime(common_recv_time) IN ( SELECT toDateTime(common_recv_time) FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ORDER BY common_recv_time DESC LIMIT 30 ) AND common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ORDER BY common_recv_time DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('All Fields Query (sub query by log id)', 'trouble-shooting', 'clickhouse', 'SELECT  *  FROM tsg_galaxy_v3.session_record AS session_record WHERE common_log_id IN ( SELECT common_log_id FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ORDER BY common_recv_time DESC LIMIT 30 ) AND common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ORDER BY common_recv_time DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Default Field Query (sub query by time)', 'trouble-shooting', 'clickhouse', 'SELECT toDateTime(common_recv_time) AS common_recv_time_str , common_log_id , common_client_ip , common_client_port , common_server_ip , common_server_port FROM tsg_galaxy_v3.session_record AS session_record WHERE toDateTime(common_recv_time) IN ( SELECT toDateTime(common_recv_time) FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ORDER BY toDateTime(common_recv_time) DESC LIMIT 30 ) AND common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ORDER BY common_recv_time DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Default Field Query (sub query by log id)', 'trouble-shooting', 'clickhouse', 'SELECT toDateTime(common_recv_time) AS common_recv_time_str , common_log_id , common_client_ip , common_client_port , common_server_ip , common_server_port FROM tsg_galaxy_v3.session_record AS session_record WHERE common_log_id IN ( select common_log_id FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ORDER BY toDateTime(common_recv_time) DESC LIMIT 30 ) AND ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'')) ORDER BY common_recv_time DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Default Field Query by Server IP (sub query by log id with Index Table)', 'trouble-shooting', 'clickhouse', 'SELECT toDateTime(common_recv_time) AS common_recv_time_str , common_log_id , common_client_ip , common_client_port , common_server_ip , common_server_port FROM tsg_galaxy_v3.session_record AS session_record WHERE common_log_id IN ( Select common_log_id FROM tsg_galaxy_v3.session_record_common_server_ip AS session_record_common_server_ip WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_log_id = ${log_id} ORDER BY toDateTime(common_recv_time) DESC LIMIT 30 ) AND ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_log_id = ${log_id} ) ORDER BY common_recv_time DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Default Field Query by Client IP (sub query by log id with Index Table)', 'trouble-shooting', 'clickhouse', 'SELECT toDateTime(common_recv_time) AS common_recv_time_str , common_log_id , common_client_ip , common_client_port , common_server_ip , common_server_port FROM tsg_galaxy_v3.session_record AS session_record WHERE common_log_id IN ( Select common_log_id FROM tsg_galaxy_v3.session_record_common_client_ip AS session_record_common_client_ip WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_log_id = ${log_id} ORDER BY toDateTime(common_recv_time) DESC LIMIT 30 ) AND ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_log_id = ${log_id} ) ORDER BY common_recv_time DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Default Field Query by Domain (sub query by log id with Index Table)', 'trouble-shooting', 'clickhouse', 'SELECT toDateTime(common_recv_time) AS common_recv_time_str , common_log_id , common_client_ip , common_client_port , common_server_ip , common_server_port FROM tsg_galaxy_v3.session_record AS session_record WHERE common_log_id IN ( Select common_log_id FROM tsg_galaxy_v3.session_record_common_server_domain AS session_record_common_server_domain WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_log_id = ${log_id} ORDER BY toDateTime(common_recv_time) DESC LIMIT 30 ) AND ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_log_id = ${log_id} ) ORDER BY common_recv_time DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('All Fields Query by Client IP (sub query by log id with index Table)', 'trouble-shooting', 'clickhouse', 'SELECT * FROM tsg_galaxy_v3.session_record AS session_record WHERE common_log_id IN ( SELECT common_log_id FROM tsg_galaxy_v3.session_record_common_client_ip AS session_record_common_client_ip WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_log_id = ${log_id} ORDER BY toDateTime(common_recv_time) DESC LIMIT 30 ) AND ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_log_id = ${log_id} ) ORDER BY common_recv_time desc LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('All Fields Query by Server IP(sub query by log id with index Table)', 'trouble-shooting', 'clickhouse', 'SELECT * FROM tsg_galaxy_v3.session_record AS session_record WHERE common_log_id IN ( SELECT common_log_id FROM tsg_galaxy_v3.session_record_common_server_ip AS session_record_common_server_ip WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_log_id = ${log_id} ORDER BY common_recv_time LIMIT 30 ) AND ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_log_id = ${log_id} ) ORDER BY common_recv_time desc LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('All Fields Query by Domain(sub query by log id with index Table)', 'trouble-shooting', 'clickhouse', 'SELECT * FROM tsg_galaxy_v3.session_record AS session_record WHERE common_log_id IN ( SELECT common_log_id FROM tsg_galaxy_v3.session_record_common_server_domain AS session_record_common_server_domain WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_log_id = ${log_id} ORDER BY common_recv_time LIMIT 30 ) AND ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_log_id = ${log_id} ) ORDER BY common_recv_time desc LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Session Logs Sent to Database Trend(Time Grain 5 minute)', 'trouble-shooting', 'clickhouse', 'SELECT toUnixTimestamp(toDateTime(toStartOfInterval(toDateTime(common_recv_time),INTERVAL 5 MINUTE))) AS "Receive Time", count(common_log_id) AS "logs" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) GROUP BY "Receive Time" LIMIT 10000', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Traffic Bandwidth Trend(Time Grain 30 second)', 'trouble-shooting', 'clickhouse', 'SELECT toDateTime(toUnixTimestamp(toDateTime(toStartOfInterval(toDateTime(common_recv_time),INTERVAL 30 SECOND)))) AS stat_time, sum(common_c2s_byte_num) AS bytes_sent, sum(common_s2c_byte_num) AS bytes_received, sum(common_c2s_byte_num + common_s2c_byte_num) AS bytes, sum(common_c2s_pkt_num + common_s2c_pkt_num) AS packets, sum(common_sessions) AS sessions FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') GROUP BY stat_time ORDER BY stat_time ASC LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Log Tend by Type (Time Grain 5 minute)', 'trouble-shooting', 'clickhouse', 'SELECT toDateTime(toUnixTimestamp(toDateTime(toStartOfInterval(toDateTime(common_recv_time),INTERVAL 5 MINUTE)))) AS stat_time, common_schema_type AS type, sum(common_sessions) AS sessions, sum(common_c2s_byte_num + common_s2c_byte_num) AS bytes, sum(common_c2s_pkt_num + common_s2c_pkt_num) AS packets FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') GROUP BY stat_time, common_schema_type ORDER BY stat_time ASC LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Traffic Metrics Analytic', 'trouble-shooting', 'clickhouse', 'SELECT round(sum(common_s2c_byte_num) * 8 / 300,2) AS trafficInBits, round(sum(common_c2s_byte_num) * 8 / 300,2) AS trafficOutBits, round(sum(common_s2c_byte_num + common_c2s_byte_num) * 8 / 300,2) AS trafficTotalBits, round(sum(common_s2c_pkt_num) / 300,2) AS trafficInPackets, round(sum(common_c2s_pkt_num) / 300,2) AS trafficOutPackets, round(sum(common_s2c_pkt_num + common_c2s_pkt_num) / 300,2) AS trafficTotalPackets, round(sum(common_sessions) / 300,2) AS sessions FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'')', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Traffic Endpoints Metrics Trend(Time Grain 5 minute)', 'trouble-shooting', 'clickhouse', 'SELECT toUnixTimestamp(toDateTime(toStartOfInterval(toDateTime(common_recv_time),INTERVAL 5 MINUTE))) AS "Receive Time", uniq(common_internal_ip) AS "Unique Internal IP", uniq(common_external_ip) AS "Unique External IP", uniq(common_subscriber_id) AS "Unique Subscriber ID", sum(coalesce(common_c2s_byte_num + common_s2c_byte_num, 0)) AS "Bytes", sum(coalesce(common_sessions, 0)) AS "Sessions" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) GROUP BY "Receive Time" LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Endpoint Unique Num by L4 Protocol', 'trouble-shooting', 'clickhouse', 'SELECT ''all'' AS type, uniq(common_client_ip) AS client_ips, uniq(common_internal_ip) AS internal_ips, uniq(common_server_ip) AS server_ips, uniq(common_external_ip) AS external_ips, uniq(common_subscriber_id) as subscriber_ids FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') UNION ALL SELECT ''tcp'' AS type, uniq(common_client_ip) AS client_ips, uniq(common_internal_ip) AS internal_ips, uniq(common_server_ip) AS server_ips, uniq(common_external_ip) AS external_ips, uniq(common_subscriber_id) as subscriber_ids FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_l4_protocol IN ( ''IPv4_TCP'', ''IPv6_TCP'' ) UNION ALL SELECT ''UDP'' AS type, uniq(common_client_ip) AS client_ips, uniq(common_internal_ip) AS internal_ips, uniq(common_server_ip) AS server_ips, uniq(common_external_ip) AS external_ips, uniq(common_subscriber_id) as subscriber_ids FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_l4_protocol IN ( ''IPv4_UDP'', ''IPv6_UDP'' )', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('One-sided Connection Trend(Time Grain 5 minute)', 'trouble-shooting', 'clickhouse', 'SELECT toDateTime(toUnixTimestamp(toDateTime(toStartOfInterval(toDateTime(common_recv_time),INTERVAL 5 MINUTE)))) AS stat_time, (CASE WHEN common_stream_dir = 1 THEN ''c2s'' WHEN common_stream_dir = 2 THEN ''s2c'' WHEN common_stream_dir = 3 THEN ''double'' ELSE ''None'' END) AS type, sum(common_sessions) AS sessions FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') GROUP BY stat_time, common_stream_dir ORDER BY stat_time ASC LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Estimated One-sided Sessions with Bandwidth', 'trouble-shooting', 'clickhouse', 'SELECT toUnixTimestamp(toDateTime(toStartOfInterval(toDateTime(common_recv_time),INTERVAL 5 MINUTE))) AS "Receive Time", sum(common_sessions) AS "sessions", sum(if(common_stream_dir <> 3, common_sessions, 0)) AS "one_side_sessions", sum(coalesce(common_c2s_byte_num + common_s2c_byte_num, 0)) AS "Bytes", round(one_side_sessions / sessions, 2) AS one_side_percent FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) GROUP BY "Receive Time" LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Estimated TCP Sequence Gap Loss', 'trouble-shooting', 'clickhouse', 'SELECT toUnixTimestamp(toDateTime(toStartOfInterval(toDateTime(common_recv_time),INTERVAL 5 MINUTE))) AS "Receive Time", sum(common_c2s_byte_num + common_s2c_byte_num) AS "bytes", sum(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen) AS "gap_loss_bytes", round(gap_loss_bytes / bytes, 2) AS gap_loss_percent FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) AND ( common_l4_protocol IN ( ''IPv4_TCP'', ''IPv6_TCP'' ) ) GROUP BY "Receive Time" LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top30 Server IP by Bytes', 'trouble-shooting', 'clickhouse', 'SELECT "server_ip" AS "server_ip" , SUM(coalesce("bytes",0)) AS "bytes" , SUM(coalesce("bytes_sent",0)) AS "Sent" , SUM(coalesce("bytes_received",0)) AS "Received" , SUM(coalesce("sessions",0)) AS "sessions" FROM ( SELECT SUM(coalesce(common_c2s_byte_num,0)) AS "bytes_sent" , SUM(coalesce(common_s2c_byte_num,0)) AS "bytes_received" , SUM(common_c2s_byte_num+common_s2c_byte_num) AS "bytes" , SUM(coalesce(common_sessions,0)) AS "sessions" , common_server_ip AS "server_ip" FROM tsg_galaxy_v3.session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) AND ( notEmpty( common_server_ip) ) GROUP BY "server_ip" ORDER BY "bytes" desc ) GROUP BY "server_ip" ORDER BY "bytes" desc LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Q27.Top30 Client IP by Sessions', 'trouble-shooting', 'clickhouse', 'SELECT common_client_ip , COUNT(*) AS sessions FROM tsg_galaxy_v3.session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') GROUP BY common_client_ip ORDER BY sessions desc LIMIT 0,30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top30 TCP Server Ports by Sessions', 'trouble-shooting', 'clickhouse', 'SELECT "Server Port" AS "Server Port", sum(coalesce("Sessions", 0)) AS "Sessions" FROM (SELECT common_server_port AS "Server Port", sum(coalesce(common_sessions, 0)) AS "Sessions" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) AND ( common_l4_protocol IN ( ''IPv4_TCP'', ''IPv6_TCP'' ) ) GROUP BY "Server Port" LIMIT 1048576) GROUP BY "Server Port" ORDER BY "Sessions" DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top30 Domian by Bytes', 'trouble-shooting', 'clickhouse', 'SELECT "domain" AS "Website Domain" , SUM(coalesce("bytes",0)) AS "Throughput" FROM ( SELECT SUM(coalesce(common_c2s_byte_num,0)) AS "bytes_sent" , SUM(coalesce(common_s2c_byte_num,0)) AS "bytes_received" , SUM(coalesce(common_c2s_byte_num+common_s2c_byte_num,0)) AS "bytes" , common_server_domain AS "domain" FROM tsg_galaxy_v3.session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) AND ( notEmpty( common_server_domain) ) GROUP BY "domain" ORDER BY "bytes" desc ) GROUP BY "domain" ORDER BY "Throughput" desc LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top30 Endpoint Devices by Bandwidth', 'trouble-shooting', 'clickhouse', 'SELECT "device_id" AS "device_id", sum(coalesce("bytes", 0)) AS "bytes", sum(coalesce("bytes_sent", 0)) AS "Sent", sum(coalesce("bytes_received", 0)) AS "Received" FROM (SELECT sum(coalesce(common_c2s_byte_num, 0)) AS "bytes_sent", sum(coalesce(common_s2c_byte_num, 0)) AS "bytes_received", sum(common_c2s_byte_num + common_s2c_byte_num) AS bytes, common_device_id AS "device_id" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) GROUP BY "device_id" ORDER BY "bytes" DESC LIMIT 1048576) GROUP BY "device_id" ORDER BY "bytes" DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top30 Domain by Unique Client IP', 'trouble-shooting', 'clickhouse', 'SELECT "Http.Domain" AS "Http.Domain", sum(coalesce("Client IP", 0)) AS "Client IP" FROM (SELECT common_server_domain AS "Http.Domain", uniq(common_client_ip) AS "Client IP" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) AND ( notEmpty(common_server_domain) ) GROUP BY "Http.Domain" ORDER BY "Client IP" DESC LIMIT 1048576) GROUP BY "Http.Domain" ORDER BY "Client IP" DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top100 Most Time Consuming Domains', 'trouble-shooting', 'clickhouse', 'SELECT "Domain" AS "Domain", avg(coalesce("Avg Establish Latency(ms)", 0)) AS "Avg Establish Latency(ms)" FROM (SELECT common_server_domain AS "Domain", avg(coalesce(common_establish_latency_ms, 0)) AS "Avg Establish Latency(ms)" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) AND ( notEmpty(common_server_domain) ) GROUP BY "Domain" LIMIT 1048576) GROUP BY "Domain" ORDER BY "Avg Establish Latency(ms)" DESC LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top30 Sources by Sessions', 'trouble-shooting', 'clickhouse', 'SELECT "source" AS "source", sum(coalesce("sessions", 0)) AS "sessions" FROM (SELECT coalesce(nullif(common_subscriber_id, ''), nullif(common_client_ip, '')) AS "source", sum(coalesce(common_sessions, 0)) AS "sessions" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) GROUP BY "source" ORDER BY "sessions" DESC LIMIT 1048576) GROUP BY "source" ORDER BY "sessions" DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top30 Destinations by Sessions', 'trouble-shooting', 'clickhouse', 'SELECT "destination" AS "destination", sum(coalesce("sessions", 0)) AS "sessions" FROM (SELECT coalesce(nullif(common_server_domain, ''), nullif(common_server_ip, '')) AS "destination", sum(coalesce(common_sessions, 0)) AS "sessions" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) GROUP BY "destination" ORDER BY "sessions" DESC LIMIT 1048576) GROUP BY "destination" ORDER BY "sessions" DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top30 Destination Regions by Bandwidth', 'trouble-shooting', 'clickhouse', 'SELECT "server_location" AS "server_location", sum(coalesce("bytes", 0)) AS "bytes", sum(coalesce("bytes_sent", 0)) AS "Sent", sum(coalesce("bytes_received", 0)) AS "Received" FROM (SELECT arrayElement(splitByString('','', common_server_location), length(splitByString('','', common_server_location))) AS "server_location", sum(coalesce(common_c2s_byte_num, 0)) AS "bytes_sent", sum(coalesce(common_s2c_byte_num, 0)) AS "bytes_received", sum(coalesce(common_c2s_byte_num + common_s2c_byte_num, 0)) AS "bytes", sum(coalesce(common_sessions, 0)) AS "sessions" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) GROUP BY "server_location" ORDER BY "bytes" DESC LIMIT 1048576) GROUP BY "server_location" ORDER BY "bytes" DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top30 URLS by Sessions', 'trouble-shooting', 'clickhouse', 'SELECT "Http URL" AS "Http URL", sum(coalesce("Sessions", 0)) AS "Sessions" FROM (SELECT http_url AS "Http URL", sum(coalesce(common_sessions, 0)) AS "Sessions" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) GROUP BY "Http URL" LIMIT 1048576) GROUP BY "Http URL" ORDER BY "Sessions" DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top30 Destination Transmission APP by Bandwidth', 'trouble-shooting', 'clickhouse', 'SELECT "server_ip" AS "server_ip", groupUniqArray(coalesce("trans_app", 0)) AS "trans_app", sum(coalesce("bytes", 0)) AS "bytes", sum(coalesce("bytes_sent", 0)) AS "Sent", sum(coalesce("bytes_received", 0)) AS "Received" FROM (SELECT sum(coalesce(common_c2s_byte_num, 0)) AS "bytes_sent", sum(coalesce(common_s2c_byte_num, 0)) AS "bytes_received", sum(common_c2s_byte_num + common_s2c_byte_num) AS "bytes", groupUniqArray(concat(common_l4_protocol, ''/'', toString(common_server_port))) AS "trans_app", common_server_ip AS "server_ip" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) AND ( notEmpty(common_server_ip) ) GROUP BY "server_ip" ORDER BY "bytes" DESC LIMIT 1048576) GROUP BY "server_ip" ORDER BY "bytes" DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Browsing Users by Website domains and Sessions', 'trouble-shooting', 'clickhouse', 'SELECT "Subscriber ID" AS "Subscriber ID", "Http.Domain" AS "Http.Domain", sum(coalesce("sessions", 0)) AS "sessions" FROM (SELECT common_server_domain AS "Http.Domain", common_subscriber_id AS "Subscriber ID", sum(coalesce(common_sessions, 0)) AS "sessions" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) AND ( notEmpty(common_server_domain) AND notEmpty(common_subscriber_id) ) GROUP BY "Http.Domain", "Subscriber ID" ORDER BY "sessions" DESC LIMIT 1048576) GROUP BY "Subscriber ID", "Http.Domain" ORDER BY "sessions" DESC LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top Domain and Server IP by Bytes Sent', 'trouble-shooting', 'clickhouse', 'SELECT "Http.Domain" AS "Http.Domain" , "Server IP" AS "Server IP" , SUM(coalesce("Bytes Sent",0)) AS "Bytes Sent" FROM ( SELECT common_server_ip AS "Server IP" , common_server_domain AS "Http.Domain" , SUM(coalesce(common_c2s_byte_num+common_s2c_byte_num,0)) AS "Bytes" , SUM(coalesce(common_c2s_byte_num,0)) AS "Bytes Sent" , SUM(coalesce(common_s2c_byte_num,0)) AS "Bytes Received" FROM tsg_galaxy_v3.session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) AND ( notEmpty( common_server_domain) ) GROUP BY "Server IP" , "Http.Domain" ORDER BY "Bytes" desc LIMIT 1048576 ) GROUP BY "Http.Domain" , "Server IP" ORDER BY "Bytes Sent" desc LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top30 Website Domains by Client IP and Sessions', 'trouble-shooting', 'clickhouse', 'SELECT "Http.Domain" AS "Http.Domain", "Client IP" AS "Client IP", sum(coalesce("sessions", 0)) AS "sessions" FROM (SELECT common_client_ip AS "Client IP", common_server_domain AS "Http.Domain", sum(coalesce(common_sessions, 0)) AS "sessions" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) AND ( notEmpty(common_server_domain) ) GROUP BY "Client IP", "Http.Domain" ORDER BY "sessions" DESC LIMIT 1048576) GROUP BY "Http.Domain", "Client IP" ORDER BY "sessions" DESC LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Domain is Accessed by Unique Client IP Trend(bytes Time Grain 5 minute)', 'trouble-shooting', 'clickhouse', 'SELECT toDateTime(intDiv(toUInt32(toDateTime(toDateTime(common_recv_time))),300)*300) AS _time , common_server_domain AS Domain, COUNT(DISTINCT(common_client_ip)) AS nums FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND notEmpty(common_server_domain) AND common_server_domain IN ( SELECT common_server_domain FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND notEmpty(common_server_domain) GROUP BY common_server_domain ORDER BY SUM(common_s2c_byte_num+common_c2s_byte_num) DESC LIMIT 5 ) GROUP BY toDateTime(intDiv(toUInt32(toDateTime(toDateTime(common_recv_time))),300)*300) , common_server_domain ORDER BY toDateTime(intDiv(toUInt32(toDateTime(toDateTime(common_recv_time))),300)*300) DESC LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Domain is Accessed by Unique Client IP Trend(sessions,Time Grain 5 minute)', 'trouble-shooting', 'clickhouse', 'SELECT toDateTime(intDiv(toUInt32(toDateTime(toDateTime(common_recv_time))),3600)*3600) AS stat_time , common_server_domain , uniq (common_client_ip) AS nums FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'')-604800 AND common_recv_time < toDateTime(''${end}'') AND common_server_domain IN ( SELECT common_server_domain FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND notEmpty(common_server_domain) GROUP BY common_server_domain ORDER BY COUNT(*) desc LIMIT 5 ) group by toDateTime(intDiv(toUInt32(toDateTime(toDateTime(common_recv_time))), 3600)*3600), common_server_domain ORDER BY stat_time desc LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Bandwidth Trend with Device ID(Time Grain 5 minute)', 'trouble-shooting', 'clickhouse', 'SELECT toUnixTimestamp(toDateTime(toStartOfInterval(toDateTime(common_recv_time),INTERVAL 5 MINUTE))) AS "Receive Time", common_device_id AS "Device ID", sum(coalesce(common_c2s_byte_num + common_s2c_byte_num, 0)) AS "Bytes" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) GROUP BY "Receive Time", "Device ID" LIMIT 10000', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Internal IP by Sled IP and Sessions', 'trouble-shooting', 'clickhouse', 'SELECT "Internal IP" AS "Internal IP", "Sled IP" AS "Sled IP", sum(coalesce("Sessions", 0)) AS "Sessions" FROM (SELECT common_sled_ip AS "Sled IP", common_internal_ip AS "Internal IP", sum(coalesce(common_sessions, 0)) AS "Sessions" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) GROUP BY "Sled IP", "Internal IP" LIMIT 1048576) GROUP BY "Internal IP", "Sled IP" ORDER BY "Sessions" DESC LIMIT 10000', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Bandwidth Trend with Internal IP (Time Grain 5 minute)', 'trouble-shooting', 'clickhouse', 'SELECT toUnixTimestamp(toDateTime(toStartOfInterval(toDateTime(common_recv_time),INTERVAL 5 MINUTE))) AS "Receive Time", sum(coalesce(common_c2s_byte_num + common_s2c_byte_num, 0)) AS "Bytes", sum(coalesce(common_c2s_pkt_num + common_s2c_pkt_num, 0)) AS "Packets", sum(coalesce(common_sessions, 0)) AS "New Sessions", sum(coalesce(common_c2s_byte_num, 0)) AS "Bytes Sent", sum(coalesce(common_s2c_byte_num, 0)) AS "Bytes Received", sum(coalesce(common_c2s_pkt_num, 0)) AS "Packets Sent", sum(coalesce(common_s2c_pkt_num, 0)) AS "Packets Received" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) AND common_client_ip=''${client_ip}'' ) GROUP BY "Receive Time" LIMIT 10000', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top30 Domains Detail with Internal IP', 'trouble-shooting', 'clickhouse', 'SELECT "Domain" AS "Domain", sum(coalesce("Sessions", 0)) AS "Sessions" FROM (SELECT common_server_domain AS "Domain", sum(coalesce(common_sessions, 0)) AS "Sessions" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) AND common_client_ip=''${client_ip}'' ) AND ( notEmpty(common_server_domain) ) GROUP BY "Domain" LIMIT 1048576) GROUP BY "Domain" ORDER BY "Sessions" DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top30 URLS Detail with Internal IP', 'trouble-shooting', 'clickhouse', 'SELECT "URL" AS "URL", sum(coalesce("Sessions", 0)) AS "Sessions" FROM (SELECT http_url AS "URL", sum(coalesce(common_sessions, 0)) AS "Sessions" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) AND common_client_ip=''${client_ip}'' ) AND ( notEmpty(http_url) ) GROUP BY "URL" LIMIT 1048576) GROUP BY "URL" ORDER BY "Sessions" DESC LIMIT 30', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top Domains with Unique Client IP and Subscriber ID', 'trouble-shooting', 'clickhouse', 'SELECT "Http.Domain" AS "Http.Domain", sum(coalesce("Unique Client IP", 0)) AS "Unique Client IP", sum(coalesce("Unique Subscriber ID", 0)) AS "Unique Subscriber ID" FROM (SELECT common_server_domain AS "Http.Domain", uniq(common_client_ip) AS "Unique Client IP", uniq(common_subscriber_id) AS "Unique Subscriber ID" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) AND ( notEmpty(common_server_domain) ) GROUP BY "Http.Domain" LIMIT 1048576) GROUP BY "Http.Domain" ORDER BY "Unique Client IP" DESC LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top100 Domains by Packets sent', 'trouble-shooting', 'clickhouse', 'SELECT "Http.Domain" AS "Http.Domain", sum(coalesce("Packets Sent", 0)) AS "Packets Sent" FROM (SELECT common_server_domain AS "Http.Domain", sum(coalesce(common_c2s_pkt_num, 0)) AS "Packets Sent" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) GROUP BY "Http.Domain" LIMIT 1048576) GROUP BY "Http.Domain" ORDER BY "Packets Sent" DESC LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Internal and External asymmetric traffic', 'trouble-shooting', 'clickhouse', 'SELECT "Internal IP" AS "Internal IP", "External IP" AS "External IP", "Sled IP" AS "Sled IP", sum(coalesce("Sessions", 0)) AS "Sessions" FROM (SELECT common_sled_ip AS "Sled IP", common_external_ip AS "External IP", common_internal_ip AS "Internal IP", sum(coalesce(common_c2s_byte_num + common_s2c_byte_num, 0)) AS "Bytes Sent+Bytes Received", sum(coalesce(common_sessions, 0)) AS "Sessions" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) AND ( common_stream_dir != 3 ) GROUP BY "Sled IP", "External IP", "Internal IP" LIMIT 1048576) GROUP BY "Internal IP", "External IP", "Sled IP" ORDER BY "Sessions" DESC LIMIT 500', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Client and Server ASN asymmetric traffic', 'trouble-shooting', 'clickhouse', 'SELECT "Client ASN" AS "Client ASN", "Server ASN" AS "Server ASN", sum(coalesce("Sessions", 0)) AS "Sessions" FROM (SELECT common_server_asn AS "Server ASN", common_client_asn AS "Client ASN", sum(coalesce(common_sessions, 0)) AS "Sessions" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) AND ( common_stream_dir != 3 ) GROUP BY "Server ASN", "Client ASN" LIMIT 1048576) GROUP BY "Client ASN", "Server ASN" ORDER BY "Sessions" DESC LIMIT 500', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top handshake latency by Website and Client IPs', 'trouble-shooting', 'clickhouse', 'SELECT "SSL.SNI" AS "SSL.SNI", "Client IP" AS "Client IP", avg(coalesce("Establish Latency(ms)", 0)) AS "Establish Latency(ms)" FROM (SELECT common_client_ip AS "Client IP", ssl_sni AS "SSL.SNI", avg(coalesce(common_establish_latency_ms, 0)) AS "Establish Latency(ms)" FROM tsg_galaxy_v3.session_record AS session_record WHERE ( ( common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') ) ) GROUP BY "Client IP", "SSL.SNI" LIMIT 1048576) GROUP BY "SSL.SNI", "Client IP" ORDER BY "Establish Latency(ms)" DESC LIMIT 500', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Domain baidu.com Drill down Client IP', 'trouble-shooting', 'clickhouse', 'select common_client_ip as "Client IP" , avg(common_establish_latency_ms) as "Establishing Time Mean(ms)", count(1) as Responses,any(common_client_location) as Location FROM tsg_galaxy_v3.session_record where  common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'')  and common_server_domain=''baidu.com'' group by "Client IP" order by Responses desc limit 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Domain baidu.com Drill down Server IP', 'trouble-shooting', 'clickhouse', 'select common_server_ip as "Server IP" , avg(http_response_latency_ms) as "Server Processing Time Mean(ms)", count(1) as Responses,any(common_server_location) as Location FROM tsg_galaxy_v3.session_record where common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') and common_server_domain=''baidu.com'' group by "Server IP" order by Responses desc limit 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Domain baidu.com Drill down URI', 'trouble-shooting', 'clickhouse', 'select http_url as "URI" , avg(http_response_latency_ms) as "Server Processing Time Mean(ms)", count(1) as Responses FROM tsg_galaxy_v3.session_record where  common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') and common_server_domain=''baidu.com'' group by "URI" order by Responses desc limit 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('L7 Protocol Metrics', 'trouble-shooting', 'clickhouse', 'select  common_l7_protocol as "Protocol" , uniq(common_client_ip) as "Clients" , uniq(common_server_ip) as "Servers", count(1) as Sessions,sum(common_c2s_byte_num+common_s2c_byte_num)  as bytes FROM tsg_galaxy_v3.session_record where common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') and notEmpty(common_l7_protocol)  group by common_l7_protocol  order by bytes desc', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('L7 Protocol SIP Drill down Client IP', 'trouble-shooting', 'clickhouse', 'select common_client_ip as "Client IP" , count(1) as Sessions,sum(common_c2s_byte_num) as "Bytes Out", sum(common_s2c_byte_num) as "Bytes In",any(common_client_location) as Location FROM tsg_galaxy_v3.session_record where common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') and common_l7_protocol=''SIP'' group by "Client IP" order by Sessions desc limit 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('L7 Protocol SIP Drill down Server IP', 'trouble-shooting', 'clickhouse', 'select common_server_ip as "Server IP" , count(1) as Sessions,sum(common_c2s_byte_num) as "Bytes Out", sum(common_s2c_byte_num) as "Bytes In",any(common_server_location) as Location FROM tsg_galaxy_v3.session_record where common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') and common_l7_protocol=''SIP'' group by "Server IP" order by Sessions desc limit 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top5 Server IP keys with Unique Client IPs Trend (Grain 5 minute)', 'trouble-shooting', 'clickhouse', 'SELECT toDateTime(intDiv(toUInt32(toDateTime(toDateTime(common_recv_time))),300)*300) AS _time , common_server_ip AS server_ip, COUNT(DISTINCT(common_client_ip)) AS nums FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'') AND common_server_ip IN ( SELECT common_server_ip FROM tsg_galaxy_v3.session_record AS session_record WHERE common_recv_time >= toDateTime(''${start}'') AND common_recv_time < toDateTime(''${end}'')  GROUP BY common_server_ip ORDER BY count(*) DESC LIMIT 5 ) GROUP BY toDateTime(intDiv(toUInt32(toDateTime(toDateTime(common_recv_time))),300)*300) , server_ip ORDER BY toDateTime(intDiv(toUInt32(toDateTime(toDateTime(common_recv_time))),300)*300) DESC LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('JSQLParserException(V4.2)', 'trouble-shooting', 'clickhouse', 'select round(tcp_logs / logs, 2) as "TCP Percentage", round(udp_logs / logs, 2) as "UDP Percentage", round(egress_bytes / bytes, 2) as "Egress Percentage", round(ingress_bytes / bytes, 2) as "Ingress Percentage", tcp_logs as "TCP Logs", udp_logs as "UDP Logs", logs as "Logs", egress_bytes as "Egress Bytes", ingress_bytes as "Ingress Bytes", bytes as "Bytes"from (select sum(if(common_l4_protocol in(''IPv4_TCP'', ''IPv6_TCP''), 1, 0)) as tcp_logs, sum(if(common_l4_protocol in(''IPv4_UDP'', ''IPv6_UDP''), 1, 0)) as udp_logs, sum(if(has(bitmaskToArray(common_flags), 256), common_c2s_byte_num, common_s2c_byte_num)) as egress_bytes, sum(if(has(bitmaskToArray(common_flags), 128), common_c2s_byte_num, common_s2c_byte_num)) as ingress_bytes, count(*) as logs, sum(common_c2s_byte_num + common_s2c_byte_num) as bytes from session_record as sub_connection where common_recv_time >= toDateTime(''${start}'') and common_recv_time < toDateTime(''${end}''))', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('All Security Rule Hits', 'trouble-shooting', 'druid', 'select rule_id as rule_id,sum(hit_count) as hits,sum(in_bytes + out_bytes) as bytes from security_rule_hits where __time >''${start}'' and __time <''${end}'' group by rule_id', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Security Rule Hits with Rule ID 0', 'trouble-shooting', 'druid', 'select rule_id as rule_id,sum(hit_count) as hits from security_rule_hits where __time >''${start}'' and __time <''${end}'' and rule_id in(0) group by rule_id', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('All Security Rule Hits Trend by 5min A', 'trouble-shooting', 'druid', 'select TIME_FORMAT(time_floor(__time,''PT5M''),''yyyy-MM-dd HH:mm:ss'') as stat_time, sum(hit_count) as hits from security_rule_hits where __time >= ''${start}'' and __time < ''${end}'' group by TIME_FORMAT(time_floor(__time,''PT5M''),''yyyy-MM-dd HH:mm:ss'') limit 10000', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Security Rule Hit Time（first and last time) A', 'trouble-shooting', 'druid', 'select rule_id,TIME_FORMAT(min(__time) ,''yyyy-MM-dd HH:mm:ss'') as first_used, TIME_FORMAT(max(__time) ,''yyyy-MM-dd HH:mm:ss'') as last_used from security_rule_hits where rule_id in(0) group by rule_id', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top 200 Security Rules with Action', 'trouble-shooting', 'druid', 'select rule_id, action, sum(hit_count) as hits from security_rule_hits where __time >= ''${start}'' and __time < ''${end}'' group by rule_id, action order by hits desc limit 200', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('All Proxy Rule Hits', 'trouble-shooting', 'druid', 'select rule_id as rule_id, sum(hit_count) as hits from proxy_rule_hits where __time >=''${start}'' and __time <''${end}'' group by rule_id', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Proxy Rule Hits with Rule ID 0', 'trouble-shooting', 'druid', 'select rule_id, sum(hit_count) as hits from proxy_rule_hits where __time >=''${start}'' and __time <''${end}'' and rule_id=0 group by rule_id', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('All Proxy Rule Hits Trend by 5min A', 'trouble-shooting', 'druid', 'select TIME_FORMAT(time_floor(__time,''PT5M''),''yyyy-MM-dd HH:mm:ss'') as stat_time, sum(hit_count) as hits from proxy_rule_hits where __time >= ''${start}'' and __time < ''${end}'' group by TIME_FORMAT(time_floor(__time,''PT5M''),''yyyy-MM-dd HH:mm:ss'') limit 10000', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Proxy Rule Hit Time（first and last time) A', 'trouble-shooting', 'druid', 'select rule_id as rule_id,TIME_FORMAT(min(__time) ,''yyyy-MM-dd HH:mm:ss'') as first_used, TIME_FORMAT(max(__time) ,''yyyy-MM-dd HH:mm:ss'') as last_used from proxy_rule_hits where rule_id in(0) group by rule_id', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top 200 Proxy Rules', 'trouble-shooting', 'druid', 'select rule_id, sum(hit_count) as hits from proxy_rule_hits where __time >= ''${start}'' and __time < ''${end}'' group by rule_id order by hits desc limit 200', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top 200 Proxy Rules with Action', 'trouble-shooting', 'druid', 'select rule_id, action, sum(hit_count) as hits from proxy_rule_hits where __time >=''${start}'' and __time <''${end}'' group by rule_id, action order by hits desc limit 200', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Proxy Action Hits', 'trouble-shooting', 'druid', 'select action as action, sum(hit_count) as hits from proxy_rule_hits where __time >= ''${start}'' and __time < ''${end}'' group by action', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Proxy Action Hits Trend by 5min', 'trouble-shooting', 'druid', 'select TIME_FORMAT(time_floor(__time,''PT5M''),''yyyy-MM-dd HH:mm:ss'') as stat_time, action as action, sum(hit_count) as hits from proxy_rule_hits where __time >= ''${start}'' and __time < ''${end}'' group by TIME_FORMAT(time_floor(__time,''PT5M''),''yyyy-MM-dd HH:mm:ss'') , action limit 10000', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Traffic Metric[Bits/s | Bytes/s | Packets/s | Sessions/s | Active Sessions]', 'trouble-shooting', 'druid', 'SELECT sum(sum_in_bytes) * 8 / 15 AS avg_in_bits_per_sec, sum(sum_out_bytes) * 8 / 15 AS avg_out_bits_per_sec, sum(sum_in_bytes + sum_out_bytes) * 8 / 15 AS avg_bits_per_sec, sum(sum_in_bytes) / 15 AS avg_in_bytes_per_sec, sum(sum_out_bytes) / 15 AS avg_out_bytes_per_sec, sum(sum_in_bytes + sum_out_bytes) / 15 AS avg_bytes_per_sec, sum(sum_in_pkts) / 15 AS avg_in_pkts_per_sec, sum(sum_out_pkts) / 15 AS avg_out_pkts_per_sec, sum(sum_in_pkts + sum_out_pkts) / 15 AS avg_pkts_per_sec, sum(sum_sessions) / 15 AS avg_sessions_per_sec, sum(max_active_sessions) AS active_sessions FROM( SELECT device_id, vsys_id, sum(in_bytes) AS sum_in_bytes, sum(out_bytes) AS sum_out_bytes, sum(in_pkts) AS sum_in_pkts, sum(out_pkts) AS sum_out_pkts, sum(sessions) AS sum_sessions, max(active_sessions) AS max_active_sessions FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' GROUP BY device_id, vsys_id)', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Traffic Metrics Bandwidth Bits IN/OUT', 'trouble-shooting', 'druid', 'SELECT stat_time AS stat_time, avg(sum_in_bytes) * 8 / 15 AS avg_in_bits_per_sec, avg(sum_out_bytes) * 8 / 15 AS avg_out_bits_per_sec, avg(sum_bytes) * 8 / 15 AS avg_bits_per_sec, max(sum_in_bytes) * 8 / 15 AS max_in_bits_per_sec, max(sum_out_bytes) * 8 / 15 AS max_out_bits_per_sec, max(sum_bytes) * 8 / 15 AS max_bits_per_sec, min(sum_in_bytes) * 8 / 15 AS min_in_bits_per_sec, min(sum_out_bytes) * 8 / 15 AS min_out_bits_per_sec, min(sum_bytes) * 8 / 15 AS min_bits_per_sec FROM( SELECT TIME_FORMAT(time_floor(__time, ''PT30S''), ''yyyy-MM-dd HH:mm:ss'') AS stat_time, sum(in_bytes) AS sum_in_bytes, sum(out_bytes) AS sum_out_bytes, sum(in_bytes + out_bytes) AS sum_bytes FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time <''${end}'' GROUP BY TIME_FORMAT(time_floor(__time, ''PT30S''), ''yyyy-MM-dd HH:mm:ss'')) GROUP BY stat_time ORDER BY stat_time ASC LIMIT 10000', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Traffic Metrics Bandwidth Bytes IN/OUT', 'trouble-shooting', 'druid', 'SELECT stat_time AS stat_time, avg(sum_in_bytes) / 15 AS avg_in_bits_per_sec, avg(sum_out_bytes) / 15 AS avg_out_bits_per_sec, avg(sum_bytes) / 15 AS avg_bits_per_sec, max(sum_in_bytes) / 15 AS max_in_bits_per_sec, max(sum_out_bytes) / 15 AS max_out_bits_per_sec, max(sum_bytes) / 15 AS max_bits_per_sec, min(sum_in_bytes) / 15 AS min_in_bits_per_sec, min(sum_out_bytes) / 15 AS min_out_bits_per_sec, min(sum_bytes) / 15 AS min_bits_per_sec FROM( SELECT TIME_FORMAT(time_floor(__time, ''PT30S''), ''yyyy-MM-dd HH:mm:ss'') AS stat_time, sum(in_bytes) AS sum_in_bytes, sum(out_bytes) AS sum_out_bytes, sum(in_bytes + out_bytes) AS sum_bytes FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time <''${end}'' GROUP BY TIME_FORMAT(time_floor(__time, ''PT30S''), ''yyyy-MM-dd HH:mm:ss'')) GROUP BY stat_time ORDER BY stat_time ASC LIMIT 10000', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Traffic Metrics Bandwidth Packets IN/OUT', 'trouble-shooting', 'druid', 'SELECT stat_time AS stat_time, avg(sum_in_pkts) / 15 AS avg_in_pkts_per_sec , avg(sum_out_pkts) / 15 AS avg_out_pkts_per_sec , avg(sum_pkts) / 15 AS avg_pkts_per_sec , max(sum_in_pkts) / 15 AS max_in_pkts_per_sec , max(sum_out_pkts) / 15 AS max_out_pkts_per_sec , max(sum_pkts) / 15 AS max_pkts_per_sec , min(sum_in_pkts) / 15 AS min_in_pkts_per_sec , min(sum_out_pkts) / 15 AS min_out_pkts_per_sec , min(sum_pkts) / 15 AS min_pkts_per_sec FROM( SELECT TIME_FORMAT(time_floor(__time, ''PT30S''), ''yyyy-MM-dd HH:mm:ss'') AS stat_time , sum(in_pkts) AS sum_in_pkts, sum(out_pkts) AS sum_out_pkts , sum(in_pkts + out_pkts) AS sum_pkts FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time <''${end}'' GROUP BY TIME_FORMAT(time_floor(__time, ''PT30S''), ''yyyy-MM-dd HH:mm:ss'')) GROUP BY stat_time ORDER BY stat_time ASC LIMIT 10000', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Traffic Metrics New Sessions Trend by 5Min', 'trouble-shooting', 'druid', 'SELECT stat_time AS stat_time, avg(sum_sessions) / 15 AS avg_sessions_per_sec , max(sum_sessions) / 15 AS max_sessions_per_sec , min(sum_sessions) / 15 AS min_sessions_per_sec FROM( SELECT TIME_FORMAT(time_floor(__time, ''PT5M''), ''yyyy-MM-dd HH:mm:ss'') AS stat_time , sum(sessions) AS sum_sessions FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time <''${end}'' GROUP BY TIME_FORMAT(time_floor(__time, ''PT5M''), ''yyyy-MM-dd HH:mm:ss'')) GROUP BY stat_time ORDER BY stat_time ASC LIMIT 10000', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Traffic Metrics Active Sessions Trend by 5Min', 'trouble-shooting', 'druid', 'SELECT stat_time AS stat_time, avg(sum_active_sessions) / 15 AS avg_active_sessions , max(sum_active_sessions) / 15 AS max_active_sessions , min(sum_active_sessions) / 15 AS min_active_sessions FROM( SELECT stat_time, sum(max_active_sessions) AS sum_active_sessions FROM( SELECT TIME_FORMAT(time_floor(__time, ''PT5M''), ''yyyy-MM-dd HH:mm:ss'') AS stat_time , device_id, vsys_id, max(active_sessions) AS max_active_sessions FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time <''${end}'' GROUP BY TIME_FORMAT(time_floor(__time, ''PT5M''), ''yyyy-MM-dd HH:mm:ss''), device_id, vsys_id) GROUP BY stat_time) GROUP BY stat_time ORDER BY stat_time ASC LIMIT 10000', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Shaping Profiles Metrics', 'trouble-shooting', 'druid', 'SELECT profile_id, sum(in_bytes + out_bytes) AS bytes , sum(in_pkts + out_pkts) AS packets , sum(in_drop_pkts + out_drop_pkts) AS drops , max(in_max_latency_us + out_max_latency_us) AS max_latency_us , avg(in_queue_len + out_queue_len) AS avg_q , max(in_queue_len + out_queue_len) AS max_q FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time <''${end}'' GROUP BY profile_id', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Rule Summary Metrics', 'trouble-shooting', 'druid', 'SELECT rule_id, TIME_FORMAT(min(__time) ,''yyyy-MM-dd HH:mm:ss'') as first_used, TIME_FORMAT(max(__time) ,''yyyy-MM-dd HH:mm:ss'') as last_used, sum(in_bytes + out_bytes) AS total_bytes FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time <''${end}'' GROUP BY rule_id', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Profile Summary Metrics', 'trouble-shooting', 'druid', 'SELECT profile_id, TIME_FORMAT(min(__time) ,''yyyy-MM-dd HH:mm:ss'') as first_used, TIME_FORMAT(max(__time) ,''yyyy-MM-dd HH:mm:ss'') as last_used, sum(in_drop_pkts + out_drop_pkts) AS drops FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time <''${end}'' GROUP BY profile_id', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Shaping Rule/Profile Throughput Trend by 5Min', 'trouble-shooting', 'druid', 'SELECT TIME_FORMAT(time_floor(__time, ''PT5M''), ''yyyy-MM-dd HH:mm:ss'') AS stat_time , sum(in_bytes) AS in_bytes, sum(out_bytes) AS out_bytes FROM traffic_shaping_rule_hits WHERE __time >= ''${start}'' AND __time <''${end}'' GROUP BY TIME_FORMAT(time_floor(__time, ''PT5M''), ''yyyy-MM-dd HH:mm:ss'') ORDER BY stat_time ASC LIMIT 10000', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Service Chaining Rule Metrics', 'trouble-shooting', 'druid', 'SELECT rule_id, sum(sent_bytes) AS sent_bytes, sum(recv_bytes) AS received_bytes , sum(sent_pkts) AS sent_packets, sum(recv_pkts) AS received_packets FROM service_chaining_rule_hits WHERE __time >= ''${start}'' AND __time <''${end}'' GROUP BY rule_id', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Service Function Forwarder Metrics', 'trouble-shooting', 'druid', 'SELECT sff_profile_id, sum(sent_bytes) AS sent_bytes, sum(recv_bytes) AS received_bytes , sum(sent_pkts) AS sent_packets, sum(recv_pkts) AS received_packets FROM service_chaining_rule_hits WHERE __time >= ''${start}'' AND __time <''${end}'' GROUP BY sff_profile_id', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Service Function Profile Metrics', 'trouble-shooting', 'druid', 'SELECT sf_profile_id, sum(sent_bytes) AS sent_bytes, sum(recv_bytes) AS received_bytes , sum(sent_pkts) AS sent_packets, sum(recv_pkts) AS received_packets FROM service_chaining_rule_hits WHERE __time >= ''${start}'' AND __time <''${end}'' GROUP BY sf_profile_id', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Service Function Profile Status', 'trouble-shooting', 'druid', 'SELECT sf_profile_id, sf_status,CASE WHEN last_active_time = 0 THEN '''' ELSE TIME_FORMAT(MILLIS_TO_TIMESTAMP( 1000 *(last_active_time)),''YYYY-MM-dd HH:mm:ss'') END AS last_active_time,CASE WHEN last_inactive_time = 0 THEN '''' ELSE TIME_FORMAT(MILLIS_TO_TIMESTAMP( 1000 * (last_inactive_time)),''YYYY-MM-dd HH:mm:ss'') END AS last_inactive_time FROM ( SELECT sf_profile_id, LATEST(sf_status) AS sf_status,MAX(CASE WHEN sf_status = 1 THEN TIMESTAMP_TO_MILLIS(TIME_PARSE(__time))/1000 ELSE 0 END) AS last_active_time,MAX(CASE WHEN sf_status = 0 THEN TIMESTAMP_TO_MILLIS(TIME_PARSE(__time))/1000 ELSE 0 END) AS last_inactive_time FROM service_function_status WHERE __time >= ''${start}'' AND __time <''${end}'' GROUP BY sf_profile_id)', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top Applications', 'trouble-shooting', 'druid', 'SELECT app_name,sum(sessions) AS sessions,sum(in_bytes) AS in_bytes,sum(out_bytes) AS out_bytes,sum(in_bytes + out_bytes) AS bytes,sum(in_pkts) AS in_packets,sum(out_pkts) AS out_packets,sum(in_pkts + out_pkts) AS packets FROM application_protocol_stat WHERE __time >= ''${start}'' AND __time <''${end}'' AND app_name IS NOT NULL GROUP BY app_name ORDER BY bytes DESC LIMIT 10', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top Client IPs', 'trouble-shooting', 'druid', 'SELECT client_ip AS client_ip,sum(sessions) AS sessions,sum(in_bytes) AS in_bytes,sum(out_bytes) AS out_bytes,sum(in_bytes + out_bytes) AS bytes,sum(in_pkts) AS in_packets,sum(out_pkts) AS out_packets,sum(in_pkts + out_pkts) AS packets FROM top_client_ips WHERE __time >= ''${start}'' AND __time <''${end}'' AND metric = ''bytes'' GROUP BY client_ip ORDER BY bytes DESC LIMIT 10', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top Server IPs', 'trouble-shooting', 'druid', 'SELECT server_ip AS server_ip,sum(sessions) AS sessions,sum(in_bytes) AS in_bytes,sum(out_bytes) AS out_bytes,sum(in_bytes + out_bytes) AS bytes,sum(in_pkts) AS in_packets,sum(out_pkts) AS out_packets,sum(in_pkts + out_pkts) AS packets FROM top_server_ips WHERE __time >= ''${start}'' AND __time <''${end}'' AND metric = ''bytes'' GROUP BY server_ip ORDER BY bytes DESC LIMIT 10', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top External IPs', 'trouble-shooting', 'druid', 'SELECT external_ip AS external_ip,sum(sessions) AS sessions,sum(in_bytes) AS in_bytes,sum(out_bytes) AS out_bytes,sum(in_bytes + out_bytes) AS bytes,sum(in_pkts) AS in_packets,sum(out_pkts) AS out_packets,sum(in_pkts + out_pkts) AS packets FROM top_external_ips WHERE __time >= ''${start}'' AND __time <''${end}'' AND metric = ''bytes'' GROUP BY external_ip ORDER BY bytes DESC LIMIT 10', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top Internal IPs', 'trouble-shooting', 'druid', 'SELECT internal_ip AS internal_ip,sum(sessions) AS sessions,sum(in_bytes) AS in_bytes,sum(out_bytes) AS out_bytes,sum(in_bytes + out_bytes) AS bytes,sum(in_pkts) AS in_packets,sum(out_pkts) AS out_packets,sum(in_pkts + out_pkts) AS packets FROM top_internal_ips WHERE __time >= ''${start}'' AND __time <''${end}'' AND metric = ''bytes'' GROUP BY internal_ip ORDER BY bytes DESC LIMIT 10', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top Server Domains', 'trouble-shooting', 'druid', 'SELECT domain,sum(sessions) AS sessions,sum(in_bytes) AS in_bytes,sum(out_bytes) AS out_bytes,sum(in_bytes + out_bytes) AS bytes,sum(in_pkts) AS in_packets,sum(out_pkts) AS out_packets,sum(in_pkts + out_pkts) AS packets FROM top_server_domains WHERE __time >= ''${start}'' AND __time <''${end}'' AND metric = ''bytes'' GROUP BY domain ORDER BY bytes DESC LIMIT 10', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top Server FQDNs', 'trouble-shooting', 'druid', 'SELECT fqdn,sum(sessions) AS sessions,sum(in_bytes) AS in_bytes,sum(out_bytes) AS out_bytes,sum(in_bytes + out_bytes) AS bytes,sum(in_pkts) AS in_packets,sum(out_pkts) AS out_packets,sum(in_pkts + out_pkts) AS packets FROM top_server_fqdns WHERE __time >= ''${start}'' AND __time <''${end}'' AND metric = ''bytes'' GROUP BY fqdn ORDER BY bytes DESC LIMIT 10', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top Subscribers', 'trouble-shooting', 'druid', 'SELECT subscriber_id,sum(sessions) AS sessions,sum(in_bytes) AS in_bytes,sum(out_bytes) AS out_bytes,sum(in_bytes + out_bytes) AS bytes,sum(in_pkts) AS in_packets,sum(out_pkts) AS out_packets,sum(in_pkts + out_pkts) AS packets FROM top_subscribers WHERE __time >= ''${start}'' AND __time <''${end}'' AND metric = ''bytes'' GROUP BY subscriber_id ORDER BY bytes DESC LIMIT 10', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top Object Lists', 'trouble-shooting', 'druid', 'SELECT object_id, sum(in_bytes) AS in_bytes, sum(out_bytes) AS out_bytes , sum(bytes) AS bytes, sum(new_in_sessions) AS new_in_sessions , sum(new_out_sessions) AS new_out_sessions, sum(sessions) AS sessions FROM object_statistics WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN(2, 3) AND object_id = 2 GROUP BY object_id ORDER BY bytes DESC LIMIT 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Object statistics', 'trouble-shooting', 'druid', 'SELECT sum(in_bytes) AS in_bytes, sum(out_bytes) AS out_bytes , sum(bytes) AS bytes, sum(new_in_sessions) AS new_in_sessions , sum(new_out_sessions) AS new_out_sessions, sum(sessions) AS sessions FROM object_statistics WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN(2, 3) AND object_id = 2', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top Item Lists', 'trouble-shooting', 'druid', 'SELECT item_id, sum(in_bytes) AS in_bytes, sum(out_bytes) AS out_bytes , sum(bytes) AS bytes, sum(new_in_sessions) AS new_in_sessions , sum(new_out_sessions) AS new_out_sessions, sum(sessions) AS sessions FROM object_statistics WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN(2, 3) AND object_id = 2 GROUP BY item_id ORDER BY bytes DESC LIMIT 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top Object Traffic Trend', 'trouble-shooting', 'druid', 'SELECT TIMESTAMP_TO_MILLIS(time_floor(stat_time * 1000,''PT1H''))/1000 AS stat_time, sum(in_bytes) AS in_bytes, avg(in_bytes) * 8 / 15 AS avg_in_bits_per_sec, sum(out_bytes) AS out_bytes, avg(out_bytes) * 8 / 15 AS avg_out_bits_per_sec, sum(bytes) AS bytes, avg(bytes) * 8 / 15 AS avg_bits_per_sec, sum(new_in_sessions) AS new_in_sessions, avg(new_in_sessions) / 15 AS avg_new_in_sessions_per_sec, sum(new_out_sessions) AS new_out_sessions, avg(new_out_sessions) / 15 AS avg_new_out_sessions_per_sec, sum(sessions) AS sessions, avg(sessions) / 15 AS avg_sessions_per_sec FROM(SELECT TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,''PT15S''))/1000 AS stat_time, sum(in_bytes) AS in_bytes, sum(out_bytes) AS out_bytes, sum(bytes) AS bytes, sum(new_in_sessions) AS new_in_sessions, sum(new_out_sessions) AS new_out_sessions, sum(sessions) AS sessions FROM object_statistics WHERE (__time >= ''${start}'' AND __time < ''2023-07-23 20:15:00'' AND vsys_id IN (2, 3) AND object_id = 2) GROUP BY TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,''PT15S''))/1000 limit 1048575) GROUP BY TIMESTAMP_TO_MILLIS(time_floor(stat_time * 1000,''PT1H''))/1000 ORDER BY stat_time ASC LIMIT 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Top Item Traffic Trend', 'trouble-shooting', 'druid', 'SELECT TIMESTAMP_TO_MILLIS(time_floor(stat_time * 1000,''PT1H''))/1000 AS stat_time, sum(in_bytes) AS in_bytes, avg(in_bytes) * 8 / 15 AS avg_in_bits_per_sec, sum(out_bytes) AS out_bytes, avg(out_bytes) * 8 / 15 AS avg_out_bits_per_sec, sum(bytes) AS bytes, avg(bytes) * 8 / 15 AS avg_bits_per_sec, sum(new_in_sessions) AS new_in_sessions, avg(new_in_sessions) / 15 AS avg_new_in_sessions_per_sec, sum(new_out_sessions) AS new_out_sessions, avg(new_out_sessions) / 15 AS avg_new_out_sessions_per_sec, sum(sessions) AS sessions, avg(sessions) / 15 AS avg_sessions_per_sec FROM(SELECT TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,''PT15S''))/1000 AS stat_time, sum(in_bytes) AS in_bytes, sum(out_bytes) AS out_bytes, sum(bytes) AS bytes, sum(new_in_sessions) AS new_in_sessions, sum(new_out_sessions) AS new_out_sessions, sum(sessions) AS sessions FROM object_statistics WHERE(__time >= ''${start}'' AND __time < ''2023-07-23 20:15:00'' AND vsys_id IN (2, 3) AND item_id = 198) GROUP BY TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,''PT15S''))/1000 limit 1048575) GROUP BY TIMESTAMP_TO_MILLIS(time_floor(stat_time * 1000,''PT1H''))/1000 ORDER BY stat_time ASC LIMIT 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Incoming Bytes, Outgoing Bytes and Bytes (Line Chart)', 'trouble-shooting', 'druid', 'SELECT TIMESTAMP_TO_MILLIS(time_floor(stat_time * 1000,''PT1H''))/1000 AS stat_time, sum(in_bytes) AS in_bytes, sum(out_bytes) AS out_bytes, sum(bytes) AS bytes FROM(SELECT TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,''PT15S''))/1000 AS stat_time, sum(in_bytes) AS in_bytes, sum(out_bytes) AS out_bytes, sum(bytes) AS bytes FROM statistics_rule WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN(2, 3) AND rule_id = 2 AND template_id = 198 AND chart_id = 1314 AND version = ''12'' GROUP BY TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,''PT15S''))/1000 limit 1048575) GROUP BY TIMESTAMP_TO_MILLIS(time_floor(stat_time * 1000,''PT1H''))/1000 ORDER BY stat_time ASC LIMIT 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Average Incoming bits/s, Average Outgoing bits/s and Average bits/s (Line Chart)', 'trouble-shooting', 'druid', 'SELECT TIMESTAMP_TO_MILLIS(time_floor(stat_time * 1000,''PT1H''))/1000 AS stat_time, avg(in_bytes) * 8 / 15 AS avg_in_bits_per_sec, avg(out_bytes) * 8 / 15 AS avg_out_bits_per_sec, avg(bytes) * 8 / 15 AS avg_bits_per_sec FROM(SELECT TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,''PT15S''))/1000 AS stat_time, sum(in_bytes) AS in_bytes, sum(out_bytes) AS out_bytes, sum(bytes) AS bytes FROM statistics_rule WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN (2, 3) AND rule_id = 2 AND template_id = 198 AND chart_id = 1314 AND version = ''12'' GROUP BY TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,''PT15S''))/1000 limit 1048575) GROUP BY TIMESTAMP_TO_MILLIS(time_floor(stat_time * 1000,''PT1H''))/1000 ORDER BY stat_time ASC LIMIT 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Unique Client IPs and Unique Server IPs (Line Chart)', 'trouble-shooting', 'druid', 'SELECT TIMESTAMP_TO_MILLIS(time_floor(stat_time * 1000,''PT1H''))/1000 AS stat_time, APPROX_COUNT_DISTINCT_HLLD(client_ip_sketch) AS unique_client_ips, APPROX_COUNT_DISTINCT_HLLD(server_ip_sketch) AS unique_server_ips FROM(SELECT TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,''PT15S''))/1000 AS stat_time, HLLD(client_ip_sketch) AS client_ip_sketch, HLLD(server_ip_sketch) AS server_ip_sketch FROM statistics_rule WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN (2, 3) AND rule_id = 2 AND template_id = 198 AND chart_id = 1314 AND version = ''12'' GROUP BY TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,''PT15S''))/1000 limit 1048575) GROUP BY TIMESTAMP_TO_MILLIS(time_floor(stat_time * 1000,''PT1H''))/1000 ORDER BY stat_time ASC LIMIT 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Histogram TCP Latency (ms) (Histogram Chart)', 'trouble-shooting', 'druid', 'SELECT HDR_GET_PERCENTILES(HDR_HISTOGRAM(latency_ms_sketch)) AS histogram_tcp_latency_ms FROM statistics_rule WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN(2, 3) AND rule_id = 2 AND template_id = 198 AND chart_id = 1314 AND version = ''12'' limit 100000', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('95th TCP Latency (ms) and 99th TCP Latency (ms) (Line Chart)', 'trouble-shooting', 'druid', 'SELECT TIMESTAMP_TO_MILLIS(time_floor(stat_time * 1000,''PT1H''))/1000 AS stat_time, APPROX_QUANTILE_HDR(latency_ms_sketch, 0.95) AS p95th_tcp_latency_ms, APPROX_QUANTILE_HDR(latency_ms_sketch, 0.99) AS p99th_tcp_latency_ms FROM(SELECT TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,''PT15S''))/1000 AS stat_time, HDR_HISTOGRAM(latency_ms_sketch) AS latency_ms_sketch FROM statistics_rule WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN (2, 3) AND rule_id = 2 AND template_id = 198 AND chart_id = 1314 AND version = ''12'' GROUP BY TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,''PT15S''))/1000 limit 1048575) GROUP BY TIMESTAMP_TO_MILLIS(time_floor(stat_time * 1000,''PT1H''))/1000 ORDER BY stat_time ASC LIMIT 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Bytes and Sessions Distributed by Application (Table or Bar Chart)', 'trouble-shooting', 'druid', 'SELECT application, sum(bytes) AS bytes, sum(sessions) AS sessions FROM statistics_rule WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN(2, 3) AND rule_id = 2 AND template_id = 198 AND chart_id = 1314 AND version = ''12'' GROUP BY application ORDER BY sessions DESC LIMIT 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Bytes and Sessions Distributed by Server IP (Table or Bar Chart)', 'trouble-shooting', 'druid', 'SELECT server_ip, sum(bytes) AS bytes, sum(sessions) AS sessions FROM statistics_rule WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN(2, 3) AND rule_id = 2 AND template_id = 198 AND chart_id = 1314 AND version = ''12'' GROUP BY server_ip ORDER BY bytes DESC LIMIT 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Bytes, Sessions and Unique Client IPs Distributed by Application and Server_ip (Table)', 'trouble-shooting', 'druid', 'SELECT application, server_ip, sum(bytes) AS bytes, sum(sessions) AS sessions, APPROX_COUNT_DISTINCT_HLLD(client_ip_sketch) AS unique_client_ips FROM statistics_rule WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN(2, 3) AND rule_id = 2 AND template_id = 198 AND chart_id = 1314 AND version = ''12'' GROUP BY application, server_ip ORDER BY unique_client_ips DESC LIMIT 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Bytes and Sessions Distributed by FQDN Category (Table or Bar Chart)', 'trouble-shooting', 'druid', 'SELECT fqdn_category, sum(bytes) AS bytes, sum(sessions) AS sessions FROM statistics_rule WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN(2, 3) AND rule_id = 2 AND template_id = 198 AND chart_id = 1314 AND version = ''12'' GROUP BY fqdn_category ORDER BY bytes DESC LIMIT 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('New Unestablished Sessions Distributed by Client IP and Server IP(Table)', 'trouble-shooting', 'druid', 'SELECT client_ip, server_ip, sum(new_unestablished_sessions) AS new_unestablished_sessions FROM statistics_rule WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN(2, 3) AND rule_id = 2 AND template_id = 198 AND chart_id = 1314 AND version = ''12'' GROUP BY client_ip, server_ip ORDER BY new_unestablished_sessions LIMIT 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Statistics Rule Bandwidth Bytes IN/OUT Trend', 'trouble-shooting', 'druid', 'SELECT TIME_FORMAT(MILLIS_TO_TIMESTAMP( 1000 *(TIMESTAMP_TO_MILLIS(time_floor(stat_time * 1000,''PT1H''))/1000)),''YYYY-MM-dd HH:mm:ss'') AS stat_time, avg(sum_in_bytes) * 8 / 15 AS avg_in_bits_per_sec, avg(sum_out_bytes) * 8 / 15 AS avg_out_bits_per_sec, avg(sum_bytes) * 8 / 15 AS avg_bits_per_sec, sum(sum_in_bytes) AS total_in_bytes, sum(sum_out_bytes) AS total_out_bytes, sum(sum_bytes) AS total_bytes FROM(SELECT TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,''PT15S''))/1000 AS stat_time, sum(in_bytes) AS sum_in_bytes, sum(out_bytes) AS sum_out_bytes, sum(in_bytes + out_bytes) AS sum_bytes FROM statistics_rule_hits WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN (2, 3) AND rule_id = 2 GROUP BY TIMESTAMP_TO_MILLIS(time_floor(0.001 * TIMESTAMP_TO_MILLIS( __time) * 1000,''PT15S''))/1000 limit 1048575) GROUP BY TIME_FORMAT(MILLIS_TO_TIMESTAMP( 1000 * (TIMESTAMP_TO_MILLIS(time_floor(stat_time * 1000,''PT1H''))/1000)),''YYYY-MM-dd HH:mm:ss'') ORDER BY stat_time ASC LIMIT 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('CK DateTime', 'trouble-shooting', 'qgw', 'select toDateTime(common_recv_time) as common_recv_time from session_record where common_recv_time >= UNIX_TIMESTAMP(''${start}'') and common_recv_time< toDateTime(UNIX_TIMESTAMP(''${end}'')) limit 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Standard DateTime', 'trouble-shooting', 'qgw', 'select FROM_UNIXTIME(common_recv_time) as common_recv_time from session_record where common_recv_time >= UNIX_TIMESTAMP(''${start}'') and common_recv_time< UNIX_TIMESTAMP(''${end}'') limit 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('count(1)', 'trouble-shooting', 'qgw', 'select count(1) from session_record where common_recv_time >= UNIX_TIMESTAMP(''${start}'') and common_recv_time< UNIX_TIMESTAMP(''${end}'')', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('count(*)', 'trouble-shooting', 'qgw', 'select count(*) from session_record where common_recv_time >= UNIX_TIMESTAMP(''${start}'') and common_recv_time< UNIX_TIMESTAMP(''${end}'')', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('UDF TIME_FLOOR_WITH_FILL', 'trouble-shooting', 'qgw', 'select TIME_FLOOR_WITH_FILL(common_recv_time,''PT5M'',''previous'') as stat_time from session_record where common_recv_time > UNIX_TIMESTAMP(''${start}'') and common_recv_time < UNIX_TIMESTAMP(''${end}'') group by stat_time', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('UDF GEO IP', 'trouble-shooting', 'qgw', 'select IP_TO_GEO(common_client_ip) as geo,IP_TO_CITY(common_server_ip) as city,IP_TO_COUNTRY(common_server_ip) as country from session_record limit 10', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Special characters', 'trouble-shooting', 'qgw', 'select * from session_record where(common_protocol_label =''/$'' or common_client_ip like''%'') limit 10', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Federation Query', 'trouble-shooting', 'qgw', 'select * from(select FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(common_recv_time,''PT5M'',''zero'')) as stat_time from session_record where common_recv_time >= UNIX_TIMESTAMP(''${start}'') and common_recv_time< UNIX_TIMESTAMP(''${end}'') group by stat_time order by stat_time asc)', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Closed session Record Logs', 'trouble-shooting', 'qgw', 'select * from session_record where common_recv_time >= UNIX_TIMESTAMP(''${start}'') and common_recv_time< UNIX_TIMESTAMP(''${end}'') AND common_client_ip=''${client_ip}'' order by common_recv_time desc limit 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
