INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Security Event Logs', 'trouble-shooting', 'qgw', 'select * from security_event where common_recv_time >= UNIX_TIMESTAMP(''${start}'') and common_recv_time< UNIX_TIMESTAMP(''${end}'') AND common_client_ip=''${client_ip}'' order by common_recv_time desc limit 0,20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
