_rcode, dns_qdcount, dns_ancount, dns_nscount, dns_arcount, dns_qname, dns_qtype, dns_qclass, dns_sub, ssl_sni, ssl_san, ssl_cn, ssl_pinningst, ssl_intercept_state, ssl_passthrough_reason, ssl_server_side_latency, ssl_client_side_latency, ssl_server_side_version, ssl_client_side_version, ssl_cert_verify, ssl_error, ssl_con_latency_ms, ssl_ja3_hash, ssl_cert_issuer, ssl_cert_subject, quic_version, quic_sni, quic_user_agent, ftp_account, ftp_url, ftp_content, ftp_link_type, app_extra_info, sip_call_id, sip_originator_description, sip_responder_description, sip_user_agent, sip_server, sip_originator_sdp_connect_ip, sip_originator_sdp_media_port, sip_originator_sdp_media_type, sip_originator_sdp_content, sip_responder_sdp_connect_ip, sip_responder_sdp_media_port, sip_responder_sdp_media_type, sip_responder_sdp_content, sip_duration_s, sip_bye, rtp_payload_type_c2s, rtp_payload_type_s2c, rtp_pcap_path, ssh_version, ssh_auth_success, ssh_client_version, ssh_server_version, ssh_cipher_alg, ssh_mac_alg, ssh_compression_alg, ssh_kex_alg, ssh_host_key_alg, ssh_host_key, ssh_hassh, stratum_cryptocurrency, stratum_mining_pools, stratum_mining_program from security_event where common_recv_time >= UNIX_TIMESTAMP(''${start}'') and common_recv_time < UNIX_TIMESTAMP(''${end}'') order by common_recv_time desc limit 100000', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Radius ON/OFF Logs For Frame IP', 'trouble-shooting', 'qgw', 'select framed_ip, arraySlice(groupUniqArray(concat(toString(event_timestamp),'':'', if(acct_status_type=1,''start'',''stop''))),1,100000) as timeseries from radius_onff_log where event_timestamp >=UNIX_TIMESTAMP(''${start}'') and event_timestamp <UNIX_TIMESTAMP(''${end}'') group by framed_ip limit 20', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Radius ON/OFF Logs For Account', 'trouble-shooting', 'qgw', 'select account, arraySlice(groupUniqArray(concat(toString(event_timestamp),'':'', if(acct_status_type=1,''start'',''stop''))),1,100000) as timeseries from radius_onff_log where event_timestamp >= UNIX_TIMESTAMP(''${start}'') and event_timestamp < UNIX_TIMESTAMP(''${end}'') group by account', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Radius ON/OFF Logs total Account number', 'trouble-shooting', 'qgw', 'select count(distinct(framed_ip)) as active_ip_num , sum(acct_session_time) as online_duration from(select any(framed_ip) as framed_ip ,max(acct_session_time) as acct_session_time from radius_onff_log where account=''000jS'' and event_timestamp >= UNIX_TIMESTAMP(''${start}'') and event_timestamp < UNIX_TIMESTAMP(''${end}'') group by acct_session_id)', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Radius ON/OFF Logs Account Access Detail', 'trouble-shooting', 'qgw', 'select max(if(acct_status_type=1,event_timestamp,0)) as start_time,max(if(acct_status_type=2,event_timestamp,0)) as end_time, any(framed_ip) as ip,max(acct_session_time) as online_duration from radius_onff_log where event_timestamp >= UNIX_TIMESTAMP(''${start}'') and event_timestamp < UNIX_TIMESTAMP(''${end}'') group by acct_session_id order by start_time desc limit 200', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Report for Client IP', 'trouble-shooting', 'qgw', 'select common_client_ip, count(*) as sessions from session_record where common_recv_time>= toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}'')))-604800 and common_recv_time< toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}''))) group by common_client_ip order by sessions desc limit 0,100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Report for Server IP', 'trouble-shooting', 'qgw', 'select common_server_ip, count(*) as sessions from session_record where common_recv_time>= toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}'')))-604800 and common_recv_time< toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}''))) group by common_server_ip order by sessions desc limit 0,100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Report for SSL SNI', 'trouble-shooting', 'qgw', 'select ssl_sni, count(*) as sessions from session_record where common_recv_time>= toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}'')))-604800 and common_recv_time< toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}''))) group by ssl_sni order by sessions desc limit 0,100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Report for SSL APP', 'trouble-shooting', 'qgw', 'select common_app_label as applicaiton, count(*) as sessions from session_record where common_recv_time>= toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}'')))-604800 and common_recv_time< toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}''))) group by applicaiton order by sessions desc limit 0,100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Report for Domains', 'trouble-shooting', 'qgw', 'select common_server_domain AS domain,SUM(coalesce(common_c2s_byte_num, 0)) AS sent_bytes,SUM(coalesce(common_s2c_byte_num, 0)) AS received_bytes,SUM(coalesce(common_c2s_byte_num, 0)+coalesce(common_s2c_byte_num, 0)) AS bytes FROM session_record WHERE common_recv_time >= toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}'')))-86400 AND common_recv_time < toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}''))) and notEmpty(domain) GROUP BY domain ORDER BY bytes DESC LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Report for Domains with unique Client IP', 'trouble-shooting', 'qgw', 'select toDateTime(intDiv(toUInt32(toDateTime(toDateTime(common_recv_time))), 300)*300) as stat_time, common_server_domain, uniq(common_client_ip) as nums from session_record where common_recv_time >= toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}'')))-86400 AND common_recv_time < toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}''))) and common_server_domain in (select common_server_domain from session_record where common_recv_time >= toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}'')))-86400 AND common_recv_time < toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}''))) and notEmpty(common_server_domain) group by common_server_domain order by SUM(coalesce(common_c2s_byte_num, 0)+coalesce(common_s2c_byte_num, 0)) desc limit 10) group by toDateTime(intDiv(toUInt32(toDateTime(toDateTime(common_recv_time))), 300)*300), common_server_domain order by stat_time asc limit 500', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Report for HTTP Host', 'trouble-shooting', 'qgw', 'SELECT http_host as host, SUM(coalesce(common_c2s_byte_num, 0)) AS sent_bytes,SUM(coalesce(common_s2c_byte_num, 0)) AS received_bytes,SUM(coalesce(common_c2s_byte_num, 0)+coalesce(common_s2c_byte_num, 0)) AS bytes FROM session_record WHERE common_recv_time>= toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}'')))-604800 and common_recv_time< toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}''))) and notEmpty(http_host) GROUP BY host ORDER BY bytes DESC limit 100 union all SELECT ''totals'' as host, SUM(coalesce(common_c2s_byte_num, 0)) AS sent_bytes, SUM(coalesce(common_s2c_byte_num, 0)) AS received_bytes, SUM(coalesce(common_c2s_byte_num, 0)+coalesce(common_s2c_byte_num, 0)) AS bytes from session_record where common_recv_time>= toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}'')))-604800 and common_recv_time< toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}''))) and notEmpty(http_host)', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Report for HTTP/HTTPS URLS with Sessions', 'trouble-shooting', 'qgw', 'SELECT http_url AS url,count(*) AS sessions FROM proxy_event WHERE common_recv_time >= toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}'')))-86400 AND common_recv_time < toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}''))) and notEmpty(http_url) GROUP BY url ORDER BY sessions DESC LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Report for HTTP/HTTPS URLS with UNIQUE Client IP', 'trouble-shooting', 'qgw', 'select toDateTime(intDiv(toUInt32(toDateTime(toDateTime(common_recv_time))), 300)*300) as stat_time, http_url, count(distinct(common_client_ip)) as nums from proxy_event where common_recv_time >= toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}'')))-86400 AND common_recv_time < toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}''))) and http_url IN(select http_url from proxy_event where common_recv_time >= toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}'')))-86400 AND common_recv_time < toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}''))) and notEmpty(http_url) group by http_url order by count(*) desc limit 10) group by toDateTime(intDiv(toUInt32(toDateTime(toDateTime(common_recv_time))), 300)*300), http_url order by stat_time asc limit 500', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Report for Subscriber ID with Sessions', 'trouble-shooting', 'qgw', 'select common_subscriber_id as user, count(*) as sessions from session_record where common_recv_time>= toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}'')))-604800 and common_recv_time< toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}''))) and notEmpty(user) group by common_subscriber_id order by sessions desc limit 0,100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Report for Subscriber ID with Bandwidth', 'trouble-shooting', 'qgw', 'SELECT common_subscriber_id as user,SUM(coalesce(common_c2s_byte_num, 0)) AS sent_bytes,SUM(coalesce(common_s2c_byte_num, 0)) AS received_bytes,SUM(coalesce(common_c2s_byte_num, 0)+coalesce(common_s2c_byte_num, 0)) AS bytes FROM session_record WHERE common_recv_time>= toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}'')))-604800 and common_recv_time< toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}''))) and notEmpty(user) GROUP BY user ORDER BY bytes DESC LIMIT 100', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Report Unique Endpoints', 'trouble-shooting', 'qgw', 'select uniq(common_client_ip) as "Client IP",uniq(common_server_ip) as "Server IP",uniq(common_internal_ip) as "Internal IP",uniq(common_external_ip) as "External IP",uniq(common_server_domain) as "Domain",uniq(ssl_sni) as "SNI" from session_record where common_recv_time>= toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}'')))-604800 and common_recv_time< toStartOfDay(toDateTime(UNIX_TIMESTAMP(''${start}'')))', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('TopN Optimizer', 'trouble-shooting', 'qgw', 'SELECT http_url AS url, SUM(common_sessions) AS sessions FROM session_record WHERE common_recv_time >= toDateTime(UNIX_TIMESTAMP(''${start}'')) AND common_recv_time < toDateTime(UNIX_TIMESTAMP(''${end}'')) AND notEmpty(http_url) GROUP BY http_url ORDER BY sessions DESC limit 10', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('Domain Baidu.com Metrics', 'trouble-shooting', 'qgw', 'select FROM_UNIXTIME(min(common_recv_time)) as "First Seen" , FROM_UNIXTIME(max(common_recv_time)) as "Last Seen" , median(http_response_latency_ms) as "Server Processing Time Median(ms)", count(1) as Responses,any(common_server_location) as Location from session_record WHERE common_recv_time >= toDateTime(UNIX_TIMESTAMP(''${start}'')) AND common_recv_time < toDateTime(UNIX_TIMESTAMP(''${end}'')) AND common_server_domain=''baidu.com''', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('TIME_FLOOR_WITH_FILL 01', 'trouble-shooting', 'qgw', 'select "Device Group" as "Device Group" ,"Data Center" as "Data Center" ,FROM_UNIXTIME("End Time") as "End Time" , sum("counter") as "counter" from(select common_device_group as "Device Group" ,common_data_center as "Data Center" ,TIME_FLOOR_WITH_FILL (common_end_time,''PT1H'',''zero'') as "End Time" ,count(common_log_id) as "counter" from session_record where common_recv_time >= toDateTime(UNIX_TIMESTAMP(''${start}'')) and common_recv_time< toDateTime(UNIX_TIMESTAMP(''${end}'')) group by "Device Group","Data Center","End Time") group by "Device Group" ,"Data Center" ,"End Time" order by "End Time" asc limit 5', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
INSERT INTO `sql_dataset` (`identifier_name`, `category`, `execute_engine`, `sql_text`, `description`, `created_time`, `modified_time`) VALUES ('TIME_FLOOR_WITH_FILL 02', 'trouble-shooting', 'qgw', 'select FROM_UNIXTIME("End Time") as "End Time" , sum("counter") as "counter" from(select common_device_group as "Device Group" ,common_data_center as "Data Center" ,TIME_FLOOR_WITH_FILL (common_end_time,''PT1H'',''zero'') as "End Time" ,count(common_log_id) as "counter" ,count(common_server_domain) as "HTTP.Domain" from security_event where ((common_recv_time >= toDateTime(''2021-10-19 00:00:00'') and common_recv_time < toDateTime(''2021-10-20 00:00:00''))) AND ( ( common_action = 2 ) ) group by "Device Group","Data Center","End Time") group by "End Time" order by "End Time" asc', NULL, '2023-08-19 00:00:00', '2023-08-19 00:00:00');
